window.BENAK_QUOTES = [{"slug":"kalendar","title_hr":"Kalendar","title_en":"The Calendar","hr":["I godina nova dođe,","djedu, baki pišeš pismo.","Sve nam tako lijepo prođe –","za godinu stariji smo!"],"en":["Then the New Year comes around,","you write \"Grandpa, Granny dear…\";","all goes by so safe and sound,","we are older by a year!"],"day":"01-01","occ_hr":"Nova godina","occ_en":"New Year's Day"},{"slug":"vrati-mi-poljupce","title_hr":"Vrati mi poljupce","title_en":"Give Me Back My Kisses","hr":["Za svaki tvoj poljubac,","po dva sam ti dao.","Reci!","Zašto šutiš,","zar me ne čuješ?","Tisuću poljubaca,","ti meni, duguješ."],"en":["For every single kiss,","I gave two back to you.","Tell me!","Why so silent,","can you not hear?","A thousand kisses","you owe me, my dear."],"day":"01-02","occ_hr":"napisano na današnji dan, 1985.","occ_en":"written on this day in 1985"},{"slug":"dobro-dosli-prijatelji-dragi","title_hr":"Dobro došli prijatelji dragi!","title_en":"Welcome, My Dear Friends!","hr":["Mnogo ljeta iza mene stoji","na plećima: sedamdeset devet.","Koliko ću? Dragi Bogo znade,","sve je dobro dok ne nađem krevet."],"en":["Many summers stand behind me now,","on my shoulders: seventy and nine.","How much longer? Only dear God knows;","till I take to my bed, all is fine."],"day":"01-03"},{"slug":"zima","title_hr":"Zima","title_en":"Winter","hr":["Sva se djeca","zdrava, čila,","kraj ognjišta sakupila","i miluju macu slatku,","koja prede sve po taktu."],"en":["All the children,","hale and bright,","round the hearth have gathered tight,","stroking Kitty, soft and sweet,","who purrs on and keeps the beat."],"day":"01-04"},{"slug":"draga-generacijo-2013","title_hr":"Draga generacijo!","title_en":"My Dear Generation!","hr":["Svi u zdravlju sreću uživali","Godinicu u ljepoti snili","Vedri dani veseli bez rada","Ne tražite Svetog Petra vrata."],"en":["May you all enjoy good health and cheer,","dream in beauty all the coming year,","bright and merry days, and work can wait:","don't go looking for Saint Peter's gate."],"day":"01-05"},{"slug":"sveta-tri-kralja","title_hr":"Sveta tri kralja","title_en":"The Three Kings","hr":["Čuo jesam da se kralj rodio.","Iz daljine ja sam dohodio.","Došao sam da mu se poklonim","i bogate darove donosim."],"en":["Word has reached me of a king's new birth;","I have come from far across the earth.","I have come to bow before him low,","bringing costly gifts I shall bestow."],"day":"01-06","occ_hr":"Sveta tri kralja","occ_en":"Epiphany"},{"slug":"da-se-ne-zaboravi","title_hr":"Da se ne zaboravi","title_en":"Lest It Be Forgotten","hr":["Još se sjećam svojega djetinjstva","i mladosti što je Sopjem prošla.","Svu ljepotu srcem dajem Sopju,","u vremenu kad je starost došla."],"en":["I remember still my childhood days","and my youth, in Sopje lived and passed;","with my heart I give all beauty to Sopje,","now that old age comes to me at last."],"day":"01-07","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"nedjelja-je-i-veselje-traje","title_hr":"Nedjelja je i veselje traje","title_en":"It's Sunday, and the Merriment Goes On","hr":["Šokadijo mili zavičaju,","najljepša si u zemaljskom raju.","Svako selo ima tamburaša,","lijepih cura i čarobnih snaša!"],"en":["Šokadija, my dear homeland, my own,","in earthly paradise the fairest known!","Each village has its tamburica band,","fair girls and charming wives on every hand!"],"day":"01-08","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"zimska-idila","title_hr":"Zimska idila","title_en":"Winter Idyll","hr":["Sniježak prši, a vatra pucketa,","topla soba kao usred ljeta.","Kamin grije, žena kavu sprema,","mačor prede, kraj kamina drijema."],"en":["The snowflakes swirl, the fire crackles bright,","the room's as warm as summer at its height.","The fireplace warms, the wife makes coffee, and","the tomcat purrs and dozes close at hand."],"day":"01-09"},{"slug":"najveca-neznalica","title_hr":"Najveća neznalica","title_en":"The Greatest Know-Nothing","hr":["Dok na cesti svoju mladost gubi,","šofer ne zna tko mu ženu ljubi.","Najveća je šofer neznalica,","dok ga ljubi autostoperica."],"en":["While on the road he wastes his youthful life,","the driver doesn't know who's kissing his wife.","The driver's the greatest know-nothing by far","when some girl hitchhiker kisses him in the car."],"day":"01-10","occ_hr":"napisano na današnji dan, 1988.","occ_en":"written on this day in 1988"},{"slug":"u-mom-narucju","title_hr":"U mom naručju","title_en":"In My Arms","hr":["U naručju kad si mome,","ja ni za šta ne znam više.","Da l' mećava snježna vije,","il' jesenje liju kiše."],"en":["When you're in my arms, my dearest,","all I know is us together,","be it snowy blizzards blowing","or the rains of autumn weather."],"day":"01-11"},{"slug":"kalendar","title_hr":"Kalendar","title_en":"The Calendar","hr":["U siječnju se drva sijeku","i djed djeci priča bajke,","u veljači snijeg još vije,","ulicama jure sanjke."],"en":["In January wood is chopped,","Grandpa's tales the children hear;","February, snow still swirling,","sledges whizzing far and near."],"day":"01-12"},{"slug":"dodi-voljena","title_hr":"Dođi voljena","title_en":"Come, My Beloved","hr":["I tugu je lakše","nositi udvoje,","kad ju se s nekim","iskreno dijeli."],"en":["Sorrow, too, is lighter","when carried by two,","if someone shares it","with a heart sincere."],"day":"01-13"},{"slug":"slavonac-u-brdima","title_hr":"Slavonac u brdima!","title_en":"A Slavonian in the Hills!","hr":["Svud je lijepo za trenutak.","Da me pusta želja mine,","ja poželih topli kutak,","bijela kruha i slanine."],"en":["Each place pleases at first look;","so this longing would be through,","all I wished was a warm nook,","some white bread, and bacon too."],"day":"01-14"},{"slug":"rodena-gruda","title_hr":"Rođena gruda","title_en":"Native Soil","hr":["Ako ti se prohtje, u bijeli svijet pođi.","Život bolne drame priređuje često.","A kada se vratiš, na grudi mi dođi.","Tu ćeš naći uvijek svoje toplo gnijezdo."],"en":["If you should wish it, go into the wide world, go!","For life will often stage its dramas full of pain.","But when you come back home, come to my breast, and so","you'll always find your own warm nest right here again."],"day":"01-15","occ_hr":"napisano na današnji dan, 1976.","occ_en":"written on this day in 1976"},{"slug":"sva-godisnja-doba","title_hr":"Sva godišnja doba","title_en":"All the Seasons","hr":["I na kraju ipak i zima je došla.","Srce mi je bolno puca od studeni.","Kao da je sreća pokraj mene prošla.","Kao santa leda srce je u meni."],"en":["And in the end, the winter came to me at last;","my aching heart is cracking open from the chill.","It's as if happiness had simply walked on past;","the heart in me is like an iceberg, cold and still."],"day":"01-16"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["Prši sniježak u noćima hladnim,","žena grije od furune bolje.","Ljubljah strasno u noćima dugim,","došla djeca, i bez moje volje."],"en":["On chilly nights the snow would flurry down;","a wife beats any stove against the chill.","I loved with passion through the long, long nights:","the children came, and that without my will."],"day":"01-17"},{"slug":"ja-mrzim","title_hr":"Ja mrzim!","title_en":"I Hate!","hr":["Ja mrzim dvorce","i ne volim kule,","tvrđave i vile","i sva zdanja","bez ljudske topline."],"en":["I hate castles","and do not love towers,","fortresses and villas","and all the buildings","without human warmth."],"day":"01-18","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["Mnoge stvari više ne trebaju,","drugačija sada su vremena,","sada čovjek po Mjesecu hoda,","ali to će ostat kuća uspomena."],"en":["So many things are needed here no more,","the times are different, and the old ways wane;","now man goes walking on the Moon, and yet","this house, a keepsake, always will remain."],"day":"01-19"},{"slug":"ljekarni-andrisic-piting","title_hr":"Ljekarni Andrišić-Piting","title_en":"To the Andrišić-Piting Pharmacy","hr":["Da bi tijelo ozdravilo,","ljekarna će svoje reći.","Ali tugu da otjera,","ova knjiga dušu liječi."],"en":["For the body to get well,","the pharmacy will have its say;","but this book will heal the soul","and will chase the sorrow away."],"day":"01-20"},{"slug":"jucer-digla-baka","title_hr":"Jučer digla baka","title_en":"Yesterday Grandma Held Her Head High","hr":["Unuče je baki","dio njene sreće,","unuče je baki","bogatstvo najveće."],"en":["A grandchild, to Granny,","is part of her pleasure;","a grandchild, to Granny,","is her greatest treasure."],"day":"01-21"},{"slug":"stiglo-nam-i-vincekovo","title_hr":"Stiglo nam i Vincekovo","title_en":"Now St Vincent's Day Has Come","hr":["Stiglo nam je već i Vincekovo,","čokoti se dobrim vinom krste","i domaćom delicijom kite,","da bi loze bile, rodne, čvrste."],"en":["Now St Vincent's Day has come already:","vine-stocks christened with good wine, and dressed","all about with homemade delicacies,","so the vines stand firm and bear their best."],"day":"01-22","occ_hr":"Vincekovo · napisano na današnji dan, 2015.","occ_en":"St Vincent's Day · written on this day in 2015"},{"slug":"prijatelju-jozi-santaku","title_hr":"Prijatelju Jozi Šantaku","title_en":"To My Friend Jozo Šantak","hr":["U ravnini Podravine","rodila me moja mati,","mnogo znanja u djetinjstvu,","nije mogla meni dati."],"en":["In the Podravina lowland","it was there my mother bore me;","much of learning, in my childhood,","she could never set before me."],"day":"01-23","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"san-o-sreci","title_hr":"San o sreći","title_en":"A Dream of Happiness","hr":["Od nepravde i od bola,","cijepala joj tuga grudi,","dok očuhov sinak spava,","mene majka u mrak budi."],"en":["From injustice and from pain","grief would cause her heart to break;","while my stepfather's son slept,","in the dark she'd make me wake."],"day":"01-24"},{"slug":"ne-mozes-umirit","title_hr":"Ne možeš umirit","title_en":"You Cannot Calm It","hr":["Umirit ne možeš uzburkano more,","nit' ugasit lavu živoga vulkana.","Ljubio bih tebe od mraka do zore.","Poljupci su tvoji mome srcu hrana."],"en":["You cannot calm the sea when it is churning,","nor quench a live volcano's lava, glowing red;","I'd kiss you from the dusk till dawn's returning.","Your kisses are the food on which my heart is fed."],"day":"01-25"},{"slug":"ugodno-druzenje-umirovljenika","title_hr":"Ugodno druženje umirovljenika","title_en":"A Pleasant Pensioners' Get-Together","hr":["Glazba svira, u srce me dira.","Ej, ne svići skoro zlatna zoro.","Bar da mi je svaki dan ovako,","makar sutra ja sa kozom or'o."],"en":["The band is playing, and my heart is swaying.","Hey, golden dawn, keep back, don't break, I pray!","If only every day could be like this,","though I should plough with a goat the next day!"],"day":"01-26"},{"slug":"ne-placi","title_hr":"Ne plači!","title_en":"Don't Cry!","hr":["Ne prosipaj biser očinjega vida,","jer me suza tvoja na obrazu peče.","Plakao bih i ja, ne mogu od stida,","zato su mi boli u grudima veće."],"en":["Do not spill the pearls that well up from your eyes,","for your tear upon my cheek burns me to the core;","I would weep as well, but shame holds back my cries,","and so the pain within my breast is all the more."],"day":"01-27","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"prva-zekina-zima","title_hr":"Prva Zekina zima","title_en":"Little Bunny's First Winter","hr":["Nešto čudno se događa,","vjetar vije, sniježak prši,","mali zeko šape gladi,","a studen mu štipa uši."],"en":["Something strange is going on:","wind is blowing, snow appears,","little bunny rubs his paws,","and the frost nips at his ears."],"day":"01-28"},{"slug":"uslisi-me-boze","title_hr":"Usliši me, Bože","title_en":"Hear Me, O God","hr":["Kako ja puno već ljeta brojim,","u fazama raznim životom svojim.","Zato se Bogu obraćam često","da meni u raju nađe mjesto."],"en":["Of summers I have counted many a score,","through all the stages life has held in store;","and so I often turn to God in prayer","that He may find a place for me up there."],"day":"01-29"},{"slug":"u-veselom-drustvu","title_hr":"U veselom društvu","title_en":"In Merry Company","hr":["\"Oprostite ima l'","tu mjesta za mene?","Ne samo za stolom,","već u srcu vašem.\"","I još sam ja htio","nešto da joj kažem,","ali kakav pogled","nepoznate žene."],"en":["\"Pardon me, is there","a place for me that's free?","Not just at your table,","but within your heart.\"","I wanted to say more,","I'd only made a start,","but what a look that lady,","a stranger, gave to me!"],"day":"01-30"},{"slug":"obitelji-nikolic","title_hr":"Obitelji Nikolić!","title_en":"To the Nikolić Family!","hr":["Bakino sunašce","kad se probudi:","pa zar ima nešto","ljepše, dragi ljudi."],"en":["Grandma's little sunshine","when he wakes, refreshed:","tell me, dear people,","what could be more blessed?"],"day":"01-31","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"most-po-kome-gazis","title_hr":"Most po kome gaziš","title_en":"The Bridge You Walk Across","hr":["Sada nosim života breme.","Most sam po kome gaziš.","A kada prođe naše vrijeme,","kasno će biti da me maziš."],"en":["Now I carry all of life's great weight,","I'm the bridge on which you tread;","and when our time has passed, it will be late,","too late for you to stroke my head."],"day":"02-01"},{"slug":"ljubav-i-bol","title_hr":"Ljubav i bol","title_en":"Love and Pain","hr":["Ljubav je davanje.","Ljubav je primanje.","I što više daješ,","to duže traje.","No, teško je trpjeti","nepravedne boli,","a još su teže,","kad ih zadaje","koga srce voli."],"en":["Love is giving.","Love is receiving.","And the more you give,","the longer it will stay.","But it's hard to suffer","pains that are not due,","and harder still","when they come your way","from one your heart loves true."],"day":"02-02"},{"slug":"pitalice","title_hr":"Pitalice","title_en":"Questions","hr":["Reci, gdje se zima","po ljetu smrzava","i pokaži krevet","u kojem snijeg spava."],"en":["Tell me, in the summer,","where does winter freeze?","Show me, too, the bed","where the snow sleeps, please."],"day":"02-03"},{"slug":"kada-ti-dosada-dusu-truje","title_hr":"Kada Ti dosada dušu truje","title_en":"When Boredom Poisons Your Soul","hr":["Kada Ti dosada dušu truje,","kada te mora iz snova budi,","kada Te očaj u životu snađe,","kada već misliš da tonu lađe,","pročitaj pjesme iz knjige ove,","pa će Ti radost ozariti snove."],"en":["When boredom is poisoning your soul,","when nightmares wake you up out of your dreams,","when in your life despair has gripped you tight,","when you believe your ships sink out of sight,","then read the poems in this book of mine,","and joy will make your dreams begin to shine."],"day":"02-04"},{"slug":"dragutinu-gibicaru","title_hr":"Dragutinu Gibičaru","title_en":"To Dragutin Gibičar","hr":["I starački dovukli se dani,","još nam srca ukrotila nije.","Ja vjerujem naše prijateljstvo","da će vjerno ostat kao prije."],"en":["And now the days of age have dragged along,","but still our hearts they have not tamed as yet;","I do believe our friendship will remain","as faithful as it was when first we met."],"day":"02-05"},{"slug":"pijanica","title_hr":"Pijanica","title_en":"The Drunkard","hr":["Više nemam žene,","da me doma čeka.","Nemam ni ognjišta,","da me toplo grije,","ni postelje nemam,","gdje se noću leži.","I zato ja pijem,","jer me piće tješi."],"en":["I've no wife any more","to wait for me at home.","I've not even a hearth","to warm me through and through,","nor have I any bed","to lie at night and rest.","And that is why I drink:","the drink consoles me best."],"day":"02-06"},{"slug":"domovino-moja","title_hr":"Domovino moja","title_en":"My Homeland","hr":["I kad umrem ti ćeš dalje cvasti","i majčinski širit krila svoja.","Dok je tebe, Šokadijo, mila,","bit će dičnih ljudi i heroja!"],"en":["And when I die, you'll blossom on and on,","spreading wide your wings as mothers do;","while you live, my dear Šokadija,","there'll be worthy folk and heroes too!"],"day":"02-07","occ_hr":"napisano na današnji dan, 1997.","occ_en":"written on this day in 1997"},{"slug":"njeznost","title_hr":"Nježnost","title_en":"Tenderness","hr":["Prođu dani kao sjena,","u brizi i stalnom radu.","Divan život uz poljupce,","i predivnu slatku nadu."],"en":["Days go by just like a shadow,","toiling, worried, as we cope;","lovely is a life with kisses","and a sweet and wondrous hope."],"day":"02-08"},{"slug":"djeca-snjeska-napravila","title_hr":"Djeca snješka napravila","title_en":"The Children Made a Snowman","hr":["Ta je radost kratka bila,","djeca snješka napustila.","Pa je snješko tužan bio,","od tuge se rastopio.","Mrkva, ugljan, metla stoje:","što od snješka ostalo je."],"en":["But that joy was soon to end:","children left their snowy friend.","Then the snowman grew so sad,","melted from the grief he had.","Carrot, coal and broom, all three,","are what's left for us to see."],"day":"02-09","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"moje-ce-te-oci-oplakati","title_hr":"Moje će te oči oplakati!","title_en":"My Eyes Will Weep for You!","hr":["Za svu sreću i tvoje poljupce.","Za svu ljubav, koju si mi dala,","za sve suze, moje radosnice,","riječ je mala da ti kažem hvala."],"en":["For all the joy we had, and all your kisses,","for all the love you gave, so full and free,","for all the tears I wept, my tears of gladness,","\"thank you\" is much too small a word from me."],"day":"02-10","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"ne-reci-da-me-volis","title_hr":"Ne reci da me voliš","title_en":"Don't Say You Love Me","hr":["Ne reci da me voliš,","to govore oči tvoje,","dok srce tvoje meni,","ljubavnu pjesmu poje."],"en":["Do not say that you love me,","it's your eyes that tell me so,","while for me your heart is singing","a love song, sweet and low."],"day":"02-11","occ_hr":"napisano na današnji dan, 1990.","occ_en":"written on this day in 1990"},{"slug":"prijatelju-glazbeniku","title_hr":"Prijatelju, glazbeniku!","title_en":"To My Friend, the Musician!","hr":["Od pjesnika umjetniku,","nek nam bude to na diku,","što stvaramo našim radom,","ovom svijetu ljepšu sliku."],"en":["Poet to an artist true:","let this be our pride: we two,","by our labour and our art,","give the world a lovelier view."],"day":"02-12","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"ima-li-sto-slade-od-meda","title_hr":"Ima li što slađe od meda","title_en":"Is There Anything Sweeter Than Honey","hr":["Ima li što slađe od meda,","kojega pčele roje?","Slađe mogu biti,","jedino usne tvoje."],"en":["Is there anything sweeter than honey","the swarming bees lay in store?","Sweeter can be only","your lips, and nothing more."],"day":"02-13"},{"slug":"kuca-u-masti","title_hr":"Kuća u mašti","title_en":"A House in My Imagination","hr":["U mašti gradim kuću.","Samo za nas dvoje,","da u njoj ostvarim","sve divne snove moje."],"en":["In fancy I am building","a house for just us two,","where all my lovely dreams","could, one by one, come true."],"day":"02-14","occ_hr":"Valentinovo · napisano na današnji dan, 1974.","occ_en":"Valentine's Day · written on this day in 1974"},{"slug":"ne-sudi","title_hr":"Ne sudi","title_en":"Don't Judge","hr":["Ne sudi po maski,","po oklopu tijela.","Za dušu moju","to si pitat htjela?","Ona je čista,","kao pamuk meka.","U zagrljaj nježni,","što te rado čeka."],"en":["Do not judge by the mask,","by the body's armoured shell.","Was it about my soul","you wanted me to tell?","It is clean and pure,","as soft as cotton, too,","in a tender embrace","that gladly waits for you."],"day":"02-15"},{"slug":"trac","title_hr":"Trač","title_en":"Gossip","hr":["Ja ne pitam nikoga kud ide.","Tko je kada s kim u krčmi pio,","ni sa čijom ženom snove snio","iako ga moje oči vide."],"en":["I don't ask a soul where he is bound,","who drank in the tavern with whom, and when,","nor whose wife he dreams with, now and then,","though my eyes can see him all around."],"day":"02-16"},{"slug":"vrati-mi-snove","title_hr":"Vrati mi snove!","title_en":"Give Me Back My Dreams!","hr":["Vrati mi se danas,","da ne plačem sutra.","Bez ljubavi tvoje","tužna su mi jutra."],"en":["Come back to me today,","so I won't weep tomorrow.","Without your love, my mornings","are mornings full of sorrow."],"day":"02-17","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"brodolomac","title_hr":"Brodolomac","title_en":"The Castaway","hr":["Dala si mi sebe i sreću i radost,","a moje patnje bile su preduge.","Probudila ljubav i zaspalu mladost,","za jedan pogled pun čežnje i tuge."],"en":["You gave yourself to me, and happiness and cheer,","when I had suffered far too long, and all in vain;","you woke my love, and woke my youth that slept, my dear,","with one sad glance, so full of longing and of pain."],"day":"02-18"},{"slug":"od-djetinjstva-do-starackih-dana","title_hr":"Od djetinjstva do staračkih dana","title_en":"From Childhood to Old Age","hr":["Proš'o Božić i godina Nova,","odjurio i Valentin sveti,","a godine na pleća se nižu,","jer nam život kao strijela leti."],"en":["Christmas gone, and gone the New Year, too,","and Saint Valentine has hurried past;","years keep piling up upon our shoulders,","for, just like an arrow, life flies fast."],"day":"02-19","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"snjezana","title_hr":"Snježana","title_en":"Snježana","hr":["Da li si od snježnih pahuljica","ili od perja rajske ptice?","Ili leptir krilima je nježno","milovao tvoje divno lice?"],"en":["Are you made of flakes of falling snow,","or of plumes from birds of paradise?","Or did a butterfly with gentle wings","stroke your face, so lovely to the eyes?"],"day":"02-20","occ_hr":"napisano na današnji dan, 1989.","occ_en":"written on this day in 1989"},{"slug":"sve-dane-moje","title_hr":"Sve dane moje","title_en":"All My Days","hr":["U svome hiru, draga,","jednom barem shvati,","više od svoga života,","nisam ti mogao dati."],"en":["In your caprice, my darling,","grasp at least this once, and know:","greater than my very life","I had nothing to bestow."],"day":"02-21"},{"slug":"uloga-zene-u-braku","title_hr":"Uloga žene u braku","title_en":"A Wife's Role in Marriage","hr":["Sto poslova žena u kući ima,","trči po cijeli dan.","Šije, pere, kuha, sprema,","dok je ne savlada san."],"en":["A hundred jobs at home the wife must do,","she's on the run all day long;","she sews, she washes, cooks and cleans,","till sleep has grown too strong."],"day":"02-22","occ_hr":"napisano na današnji dan, 2009.","occ_en":"written on this day in 2009"},{"slug":"cvjetni-san","title_hr":"Cvjetni san","title_en":"A Dream of Flowers","hr":["Njen prozor je sada prazan","ni cvijeta na njemu nema,","kapak te stare roletne","usamljen na njemu drijema."],"en":["Now her window's standing empty,","not a flower does it keep,","and the shutter of the old blind","hangs there lonely, half asleep."],"day":"02-23"},{"slug":"jozi-dubrovicu","title_hr":"Jozi Dubroviću","title_en":"To Jozo Dubrović","hr":["Kad radosno srce kuca,","Toj ljepoti nema kraja,","S prijateljem sreću dijelit,","Od tog nema ljepšeg raja."],"en":["When the heart is beating gladly,","to that beauty there's no end;","there's no lovelier paradise","than to share joy with a friend."],"day":"02-24","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"saljes-li-mi-snove","title_hr":"Šalješ li mi snove","title_en":"Do You Send Me Dreams","hr":["Od kuda bih znao da me željno ljubiš","kada ne bi meni svoje snove slala?","U zagrljaj nježni da se meni nudiš,","da bi meni svoje medne usne dala."],"en":["How would I know you long to kiss me, dear,","if you had never sent your dreams my way?","That in my tender arms you'd nestle near,","and on my lips your honeyed lips you'd lay?"],"day":"02-25"},{"slug":"dva-potoka-dvije-rijeke","title_hr":"Dva potoka, dvije rijeke","title_en":"Two Streams, Two Rivers","hr":["Na svom putu u prirodi,","svaka voda teče vodi,","pa se tako sve po malo,","iz potoka rijeka rodi."],"en":["Out in nature, on it flows;","water on to water goes;","and so, gently, bit by bit,","from a stream a river grows."],"day":"02-26"},{"slug":"ljubav-nekada-i-sada","title_hr":"Ljubav nekada i sada","title_en":"Love Then and Now","hr":["Sada više ne kaže:","\"Oh, mužiću zdravo!\"","Već u bradu promrsi:","\"Odnio te đavo!\""],"en":["She no longer says,","\"Oh, hubby, hello!\"","She mutters low instead:","\"To the devil you go!\""],"day":"02-27"},{"slug":"visibaba","title_hr":"Visibaba","title_en":"The Snowdrop","hr":["Visibaba nježna, mala,","prevarila ljubičicu:","uzela je lopaticu","i snijeg bijeli razbacala,","prije nje je procvjetala."],"en":["Little snowdrop, frail and small,","played the violet a trick:","took a little shovel, quick,","flung away the white snowfall,","and bloomed before her, first of all."],"day":"02-28"},{"slug":"zbrkani-snovi","title_hr":"Zbrkani snovi","title_en":"Muddled Dreams","hr":["Slušajte me, djeco, sada:","probudih se jednog jutra,","mjesto zore suton pada –","mislim da je bilo sutra."],"en":["Listen, children, what I say:","I woke up one morning, when","dusk instead of dawn held sway;","I think it was tomorrow then."],"day":"02-29"},{"slug":"opijelo-ljubavi","title_hr":"Opijelo ljubavi","title_en":"Requiem for Love","hr":["Za nagradu meni, što sam suze briso',","procvjetat će rupčić, k'o mirisna ruža,","jer je u njem sjeme, njena topla suza."],"en":["As my reward for all the tears that I have dried,","my handkerchief will blossom like a fragrant rose,","for there's a seed in it, her own warm tear, that grows."],"day":"03-01","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"sretan-ti-rodendan","title_hr":"Sretan ti rođendan","title_en":"Happy Birthday to You","hr":["U životu sretna bila","bez imalo tužne sjene.","A najljepše kad ti bude,","ti se onda sjeti mene."],"en":["May your life be glad and happy,","never shadowed, sorrow-free;","and when life is at its fairest,","then, my dear, remember me."],"day":"03-02","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"lastavica","title_hr":"Lastavica","title_en":"The Swallow","hr":["Lasto, ptico mila","proljeća vjesniče!","Jesi li umorna","od dugoga leta?","Volim tebe, lasto!","Ti mi nosiš sreće","i toplo proljeće.","Puno divno cvijeta."],"en":["Swallow, darling bird,","herald of the spring!","Are you tired out","from your lengthy flight?","How I love you, swallow!","You bring luck and cheer","and warm spring each year,","flowers fair and bright."],"day":"03-03"},{"slug":"majka","title_hr":"Majka","title_en":"Mother","hr":["Kada dijete noću plače,","iz snova kada se budi,","da čedu svome utjehu nađe,","majka ga svija na grudi."],"en":["When a child cries in the night,","waking from its dreams in fear,","to find comfort for her little one,","mother holds it to her bosom near."],"day":"03-04","occ_hr":"napisano na današnji dan, 1980.","occ_en":"written on this day in 1980"},{"slug":"dimnjacarska-tragedija","title_hr":"Dimnjačarska tragedija","title_en":"The Chimney Sweeps' Tragedy","hr":["Ne može se nikad ničim platit","tužnoj majci boli nanesene,","a niti se nikad mogu vratit","mladom biću snove raznesene."],"en":["Nothing ever can repay the cost","of the pain the grieving mother bore;","nor the young man's dreams, blown apart and lost,","ever be returned to him once more."],"day":"03-05"},{"slug":"sretna-proljeca","title_hr":"Sretna proljeća","title_en":"Happy Springtimes","hr":["Jednog dana ozari me sunce,","ozari me i sunce i sreća.","Poljupcima koje si mi dala,","sretna su mi svanula proljeća."],"en":["One day I was lit up by the sun,","lit up by the sun and by delight;","with the kisses that you gave to me,","happy springtimes dawned for me, so bright."],"day":"03-06"},{"slug":"sokadijo-moj-voljeni-kraju","title_hr":"Šokadijo moj voljeni kraju","title_en":"Šokadija, My Beloved Land","hr":["Slavonijo moj mirisni cvijetu,","najljepša si na čitavom svijetu.","Nikada te neću nikom dati,","vječito ću tebe svojom zvati."],"en":["Slavonia, my fragrant flower, you","are loveliest the whole wide world through;","I'll never give you up to others, never;","I'll call you mine, and only mine, forever."],"day":"03-07","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"zena","title_hr":"Žena","title_en":"Woman","hr":["Žena je najljepša bajka,","Kao sestra,","Kao supruga,","Kao majka."],"en":["Woman is the fairest tale in life,","as a sister,","as a mother,","as a wife."],"day":"03-08","occ_hr":"Dan žena","occ_en":"International Women's Day"},{"slug":"ja-te-volim","title_hr":"Ja te volim","title_en":"I Love You","hr":["Svalio se kamen,","kamen sudbine","na grudi moje,","pa mi srce smrvi.","Zašto nisam tvoj,","draga, samo tvoj?","Ljubavi moja,","jedini i prvi."],"en":["A stone has tumbled,","the stone of fate,","upon my breast,","and my heart has burst.","Why am I not yours,","darling, only yours?","My love, my own,","your only one, your first."],"day":"03-09"},{"slug":"ima-li-sto-ljepse","title_hr":"Ima li što ljepše","title_en":"What Could Be More Lovely","hr":["Kada žena voli","i kada je voljena,","ona je Afrodita","svome Adonisu."],"en":["When a woman loves","and when she is loved,","she is Aphrodite","to her own Adonis."],"day":"03-10"},{"slug":"pored-nase-rijeke","title_hr":"Pored naše rijeke","title_en":"Beside Our River","hr":["Sjetim se tebe kad prođem kraj rijeke,","gledajući dvoje gdje se sretno ljube.","Kao da mi šapću iz daljina jeke:","Volim te, mili! A riječi se gube."],"en":["I think of you whenever by the river I stroll","and see two lovers kissing happily nearby;","as though the distant echoes whispered to my soul:","\"I love you, dear!\" — and then the words just fade and die."],"day":"03-11"},{"slug":"izmedu-htjenja-i-mogucnosti","title_hr":"Između htjenja i mogućnosti","title_en":"Between Wanting and Being Able","hr":["Naša mladost najljepše je doba,","a ljubav je zato da se proba."],"en":["Of all our days, our youth's the very best,","and love is there for putting to the test."],"day":"03-12","occ_hr":"napisano na današnji dan, 2004.","occ_en":"written on this day in 2004"},{"slug":"zelene-su-oci-tvoje","title_hr":"Zelene su oči tvoje","title_en":"Green Are Those Eyes of Yours","hr":["Zelene su oči tvoje","sve bogatstvo meni bile.","Kao čašu rujnog vina","moje su ih usne pile."],"en":["Those green eyes of yours, my darling,","were my riches and my treasure;","like a glass of red wine, brimming,","my lips drank them in with pleasure."],"day":"03-13"},{"slug":"haiku","title_hr":"Haiku","title_en":"Haiku","hr":["PROLJEĆE:","Zima dala pete,","topola baca perje,","klepeću rode."],"en":["Spring:","Winter's taken to its heels,","the poplar sheds its feathers,","the storks clack their bills."],"day":"03-14"},{"slug":"u-mom-narucju","title_hr":"U mom naručju","title_en":"In My Arms","hr":["Kad milujem tebe, draga,","meni ljepše sreće nije.","Proljetne mi ruže cvatu","i ljetno me sunce grije."],"en":["When I stroke you, oh, my darling,","sweeter joy is past my knowing;","roses of the spring are blooming,","and the summer sun is glowing."],"day":"03-15"},{"slug":"sjecanje-na-djetinjstvo","title_hr":"Sjećanje na djetinjstvo","title_en":"Remembering My Childhood","hr":["I sad kad se sjetim srce me zazebe.","Na svakom koraku, bijedu sam susreto.","Nikada se nisam stidio sam sebe,","jer poštenje meni bilo je presveto."],"en":["Remembering it now, a chill goes through my frame.","At every step I met with poverty and need;","yet I have never had to hang my head in shame,","for honesty to me was sacred, as a creed."],"day":"03-16","occ_hr":"napisano na današnji dan, 1976.","occ_en":"written on this day in 1976"},{"slug":"ne-mogu-te-zaboraviti","title_hr":"Ne mogu te zaboraviti","title_en":"I Cannot Forget You","hr":["I nikada ne ću zaboravit moći,","treptaj tvoga tijela u mom zagrljaju,","u naručju tvome k'o da sam u raju,","ni tvoj tihi šapat: kada ćeš mi doći?"],"en":["And never, ever shall I manage to forget","your body's trembling as I held you close to me,","and in your arms, as though in heaven I would be,","nor how you'd whisper: \"When will you come? How long yet?\""],"day":"03-17"},{"slug":"suha-kora-prove","title_hr":"Suha kora prove","title_en":"The Dry Crust of Cornbread","hr":["A kad shvatih tu razliku","među ljudstvom što se rađa.","I ta suha kora prove","bila mi je tada slađa."],"en":["And when I grasped the difference,","grown between the rich and poor,","even that dry cornbread crust","tasted sweeter than before."],"day":"03-18","occ_hr":"napisano na današnji dan, 1976.","occ_en":"written on this day in 1976"},{"slug":"pjesma-sinu","title_hr":"Pjesma sinu!","title_en":"A Poem for My Son!","hr":["Ti još i ne znaš, kako bi i znao,","koliko te moje biće silno voli,","kada budeš svoje čedo sinom zvao","tek ćeš onda znati za strepnje i boli."],"en":["You do not know it yet (and how could you have known)","how mightily my whole being loves you so;","but when you call a son of yours your very own,","then only will you know the dread, the pain, the woe."],"day":"03-19","occ_hr":"Josipovo, Dan očeva","occ_en":"St Joseph's Day, Father's Day"},{"slug":"na-poklon-osnovnoj-skoli-sopje","title_hr":"Na poklon Osnovnoj školi Sopje","title_en":"A Gift to the Sopje Primary School","hr":["Našoj školi darujem tu knjigu,","kao spomen mog djetinjstva znaci,","kroz te pjesme ja ostavljam sebe,","nek' je vide i budući đaci."],"en":["I give this book to our school to keep,","a keepsake of my childhood, as a sign;","in these poems here I leave myself behind:","may future pupils see me in each line."],"day":"03-20"},{"slug":"pjesnikova-zelja-2011","title_hr":"Pjesnikova želja","title_en":"The Poet's Wish","hr":["JA VAM DJECO DONOSIM PROLJEĆE","TOPLO VRIJEME I MIRISNO CVIJEĆE!"],"en":["DEAR CHILDREN, HERE'S THE SPRING I BRING TO YOU:","WARM WEATHER, AND SWEET-SCENTED FLOWERS TOO!"],"day":"03-21","occ_hr":"Svjetski dan poezije i prvi dan proljeća · napisano na današnji dan, 2011.","occ_en":"World Poetry Day, first day of spring · written on this day in 2011"},{"slug":"ja-obicni-smrtnik","title_hr":"Ja obični smrtnik!","title_en":"I, an Ordinary Mortal!","hr":["Zar imam pravo,","da te nježno ljubim?","Zar imam pravo,","da ti snove kidam,","da ti se u srcu","k'o skitnica skitam?"],"en":["Have I the right","to kiss you tenderly?","Have I the right","to tear your dreams away,","to wander in your heart","like a vagabond astray?"],"day":"03-22"},{"slug":"trac","title_hr":"Trač","title_en":"Gossip","hr":["Ja vas molim i ljudi i žene,","počistite ispred svoga praga,","ne tražite sad okolo vraga,","Ostavite vi na miru mene."],"en":["Men and women, this I do implore:","sweep before your own door, keep it clear,","don't go looking round for devils near,","leave me be in peace, I ask no more."],"day":"03-23"},{"slug":"odgovor-drenovcanke","title_hr":"Odgovor Drenovčanke","title_en":"The Drenovci Woman's Reply","hr":["Reći ću ti što bih htjela:","da polako život teče,","u životu mome bolnom,","puno zdravlja, malo sreće."],"en":["I will tell you what I'd want:","that my life flow on at leisure,","and, in all my life of pain,","lots of health, of joy a measure."],"day":"03-24","occ_hr":"napisano na današnji dan, 2007.","occ_en":"written on this day in 2007"},{"slug":"djeda-daje-knjigu-svom-unuku","title_hr":"Djeda daje knjigu svom unuku!","title_en":"Grandpa Gives a Book to His Grandson!","hr":["Kada djedu u zagrljaj kreće,","djeda će ga staviti u krilo.","Obadva će blistati od sreće,","oko srca bit će njima milo."],"en":["When off he runs to Grandpa's warm embrace,","then Grandpa lifts him up onto his knee;","the two will shine with joy on either face,","and warm around their hearts they both will be."],"day":"03-25","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"sretna-proljeca","title_hr":"Sretna proljeća","title_en":"Happy Springtimes","hr":["Ne znam gdje si do sad bila, draga.","Da l' pod snijegom k'o ljubica mala?","Zbog ljepote te čarobne noći,","ti si meni svoju ljubav dala."],"en":["I don't know where you have been, my dear —","under snow, a violet, could it be?","For the beauty of that magic night","you have given all your love to me."],"day":"03-26"},{"slug":"moja-velika-otkrica","title_hr":"Moja velika otkrića","title_en":"My Great Discoveries","hr":["Htio sam svijetu","sve najbolje dati,","al´ me nije moja","razumjela mati."],"en":["I wanted to give","the world all that's good,","but my own mother","never understood."],"day":"03-27"},{"slug":"valpovacke-poete","title_hr":"Valpovačke poete","title_en":"Valpovo's Poets","hr":["Kad napiše svoju knjigu,","pjesniku je svakom dika","pa i onda, kad ga nema,","ostala je časna slika."],"en":["When he's written his own book,","every poet feels the pride;","even when he's gone from us,","his honoured image will abide."],"day":"03-28","occ_hr":"napisano na današnji dan, 2007.","occ_en":"written on this day in 2007"},{"slug":"proljece","title_hr":"Proljeće","title_en":"Spring","hr":["Okopnio snijeg,","proljeće je stiglo.","Sluti se toplina sunca.","Trava polako rosu pije,","djetlić već drvo kljuca."],"en":["The snow has thawed away,","and spring is here at last.","You feel the warmth of the sun.","The grass drinks slowly of the dew,","the woodpecker's tapping has begun."],"day":"03-29"},{"slug":"uslisi-me-boze","title_hr":"Usliši me, Bože","title_en":"Hear Me, O God","hr":["Pa kad uđu kojima je dato,","znam da ću i ja imati sreće","i meni ćeš mjesta dati zato,","jer srce je Tvoje od neba veće!"],"en":["And when they've entered, those You've granted grace,","I know that I'll be lucky by and by,","and You will give me, too, a little place,","because Your heart is bigger than the sky!"],"day":"03-30"},{"slug":"slikar-zeko","title_hr":"Slikar zeko","title_en":"Bunny the Painter","hr":["Jutros se u dvorištu","digla strašna graja,","jer netko je kokicama","ofarbao jaja."],"en":["In the yard this very morning","such a racket rose:","someone painted all the hens' eggs,","who, nobody knows!"],"day":"03-31"},{"slug":"upozorenje-1994","title_hr":"Upozorenje","title_en":"A Warning","hr":["Kad učiniš to nedjelo,","u tuđi ćeš posjed zaći,","razočarat ćeš se jako,","jer što tražiš, nećeš naći.","U toj zgradi ništa nema,","što bi tebi koristilo.","A motiku za kopanje,","nikad nisi ni volio."],"en":["When you've done this wicked deed,","stepped inside another's place,","you'll be sorely disappointed:","what you're after? Not a trace.","In this building there is nothing","that would help you, great or small;","and a hoe to dig the soil","you have never loved at all."],"day":"04-01"},{"slug":"jeka","title_hr":"Jeka","title_en":"Echo","hr":["Ja te stvarno volim,","ako ti sada kažem,","vjerovati nećeš,","reći ćeš da lažem.","Volim te, volim te, volim!","Taj odjek divne jeke,","u srcu mi snažno bruji,","k'o žubor gorske rijeke."],"en":["I truly, really love you;","if I tell you today,","you never will believe me:","\"You're lying!\" you will say.","I love you, love you, love you!","That lovely echo's ring","keeps humming in my heart","like a murmuring mountain spring."],"day":"04-02","occ_hr":"napisano na današnji dan, 1979.","occ_en":"written on this day in 1979"},{"slug":"pitalice","title_hr":"Pitalice","title_en":"Questions","hr":["Pokaži, mi tata,","kako trava raste","i, molim te, reci,","kud odlaze laste?","Po dalekom jugu","laste se skitaju.","I tamo su djeca","što isto pitaju."],"en":["Show me, Daddy, please,","how the grass can grow,","and tell me, won't you,","where the swallows go?","Far down in the south","is where the swallows roam,","and children there ask too","the same as you at home."],"day":"04-03"},{"slug":"zivot-penzionera","title_hr":"Život penzionera","title_en":"A Pensioner's Life","hr":["A izbori kada prođu,","nastavlja se priča stara.","Penzioner k'o i prije","mali je k'o bubamara."],"en":["When elections have gone by,","back comes the old tale, word for word:","and the pensioner, as ever,","is as small as a ladybird."],"day":"04-04","occ_hr":"napisano na današnji dan, 1992.","occ_en":"written on this day in 1992"},{"slug":"pijanica","title_hr":"Pijanica","title_en":"The Drunkard","hr":["Što mi srce para,","dira stare rane?","Dok mi vrijeme tiho","odbrojava dane."],"en":["What tears my heart apart","and stirs old wounds long past?","And time, so quietly,","counts down the days I'll last."],"day":"04-05"},{"slug":"brodolomac","title_hr":"Brodolomac","title_en":"The Castaway","hr":["Ja opet živim, gledam žarko sunce","i jutarnju rosu kako trava pije.","I dalje moje spavalo bi srce,","da ga tvoja ljubav probudila nije."],"en":["I live again; I see the burning sun on high","and how the thirsty grass drinks up the morning dew;","and to this day my heart in slumber still would lie,","if your love had not come and woken it anew."],"day":"04-06","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"kalendar","title_hr":"Kalendar","title_en":"The Calendar","hr":["U ožujku visibaba","ispod snijega izviruje.","U travnju već trava raste","i cvrkut se ptica čuje."],"en":["March, and there's the snowdrop peeping","out from underneath the snow.","April, and the grass is growing,","birds are chirping, high and low."],"day":"04-07"},{"slug":"za-uskrs-se-farba-jaje","title_hr":"Za Uskrs se farba jaje","title_en":"At Easter We Dye the Eggs","hr":["Eto nam se Uskrs javlja,","bit će dječici veselja,","jaja ćemo ofarbati,","to je naša draga želja."],"en":["Easter's here, it's come to call,","little children will be glad;","we'll be dyeing eggs, the dearest","wish that we have ever had."],"day":"04-08","occ_hr":"uskrsno vrijeme","occ_en":"Eastertide"},{"slug":"sokacki-obicaji","title_hr":"Šokački običaji","title_en":"Šokac Customs","hr":["Volim kad se ljubav sokacima vodi.","Volim škripu đerma i seosku viku.","Volim kada mjesec sa zvijezdama hodi,","na toj mjesečini volim svoju diku."],"en":["I love when the lanes see the lovers go by,","I love the well-sweep's creaking, the village's call,","I love when the moon strolls with stars through the sky,","in that moonlight I love my sweetheart best of all."],"day":"04-09","occ_hr":"napisano na današnji dan, 1994.","occ_en":"written on this day in 1994"},{"slug":"tri-majstora","title_hr":"Tri majstora","title_en":"Three Craftsmen","hr":["Ja zaista ne znam reći","što je za nas najvažnije,","ali blato, kiša, studen –","to je za nas najstrašnije.","I majstori tad će znati:","ne vrijedi se prepirati.","Ta vidjet će oni lako","da su vrijedni podjednako."],"en":["Truly, I can't really say","which one serves us all the best,","but the mud, the rain, the cold —","these we fear above the rest.","Then the craftsmen all will know","there's no use in quarrelling so;","for they'll easily now see","they are worth the same, all three."],"day":"04-10"},{"slug":"umirovljenicki-jadi","title_hr":"Umirovljenički jadi","title_en":"A Pensioner's Woes","hr":["Kad pogledam što u kasi osta,","taman, brale, za rakiju dosta.","Da popijem i ublažim tugu","čekajući crkavicu drugu."],"en":["And when I see what's left inside my till,","there's just enough, old mate, for rakija still,","to drink it down and ease my grief a bit,","and wait for the next pittance after it."],"day":"04-11"},{"slug":"ja-mrzim","title_hr":"Ja mrzim!","title_en":"I Hate!","hr":["Mrzim gramzljivost","svu bez pardona","i slatku fasadu","pokvarene duše.","Ja mrzim sjaj,","ljudskog licemjerstva,","uvijeno u fino ruho bontona."],"en":["I hate greed,","all of it, without regret,","and the sweet façade","of a rotten soul.","I hate the glitter","of human hypocrisy,","wrapped in the fine garb of etiquette."],"day":"04-12"},{"slug":"ljubicice","title_hr":"Ljubičice","title_en":"Violets","hr":["Kao dio neba,","kao oči tvoje,","ljubičice plave","kraj puteljka stoje.","Sjećaš se, mila,","kada sam ih brao,","uz poljupce slatke,","tebi darovao?"],"en":["Like a piece of the sky","and like your eyes, too,","beside the path there stand","the violets of blue.","Do you still remember,","dear, when I picked a few","and with sweet kisses","made them a gift to you?"],"day":"04-13"},{"slug":"draga-uspomena","title_hr":"Draga uspomena","title_en":"A Cherished Memory","hr":["I svu bol i suze, što mi srce rani.","Kada tebe sretnem, bit ćeš tuđa žena.","I sva ljubav naša i svi sretni dani,","za mene će biti draga uspomena."],"en":["And all the pain and tears that leave my heart so sore;","when next I meet you, you'll be someone else's wife.","And all our love, and all the happy days before,","for me will be a cherished memory, all my life."],"day":"04-14","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"seljacke-idile","title_hr":"Seljačke idile","title_en":"Village Idylls","hr":["Uranio Šokac u svitanje,","ormu sprema i dorate preže.","Spremio se, ide na oranje,","taj ga nagon od djetinjstva veže."],"en":["At the break of day the Šokac rose,","gets the harness, hitches up the bays;","ready now, off to the plough he goes,","drawn by instinct since his boyhood days."],"day":"04-15"},{"slug":"marijanci-dika-slavonije","title_hr":"Marijanci dika Slavonije","title_en":"Marijanci, Pride of Slavonia","hr":["Trgovina ovdje ima dosta","i robe je od njih svaka puna.","Kupili bi ljudi sve i svašta,","ali narod nema dosta kuna."],"en":["Of shops, there are quite a few round here,","and each one's full of goods of every sort;","people would buy anything at all,","but their kunas always come up short."],"day":"04-16","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"cvjetni-san","title_hr":"Cvjetni san","title_en":"A Dream of Flowers","hr":["Sve je tako brzo prošlo,","kao vjetrom odnesen dan,","i cvijeće sa tog prozora","za mene je ostao san."],"en":["All of it has passed so quickly,","like a day the wind has swept,","and the flowers at that window","only in my dreams are kept."],"day":"04-17"},{"slug":"lijepo-je-biti-voljen","title_hr":"Lijepo je biti voljen","title_en":"It's Lovely to Be Loved","hr":["Lijepo je biti voljen","i kada iskreno ljubiš.","Kada svoje tople usne","voljenom biću nudiš."],"en":["It is lovely to be loved,","and to love sincerely too,","when you offer your warm lips","to the one who's loved by you."],"day":"04-18"},{"slug":"moje-ce-te-oci-oplakati","title_hr":"Moje će te oči oplakati!","title_en":"My Eyes Will Weep for You!","hr":["Ne provodi uzaludno mladost!","Ne ljubi me, voljena djevojko!","Život tužan, a rijetka je radost.","Srce mi je kao pelin gorko."],"en":["Don't spend your youth in vain, don't waste it so!","Don't love me, darling girl whom I adore!","For life is sad, and joy is rare, you know.","My heart is bitter wormwood to the core."],"day":"04-19"},{"slug":"dijaspora","title_hr":"Dijaspora","title_en":"Diaspora","hr":["Oduvijek je kod nas","bila glad i bijeda,","u Ameriku je otišao","moj voljeni djeda.","Zatim je Europa","otvorila vrata,","tu je arbajtovo","moj rođeni tata."],"en":["Here hunger and poverty","have always held sway;","and so my dear old grandad went","to America, far away.","Then Europe in turn","flung open its gate,","and there my own father","did his arbeit, early and late."],"day":"04-20"},{"slug":"kratki-dani","title_hr":"Kratki dani","title_en":"Short Days","hr":["Blagi pogled oka tvoga","i obrazi nježni tvoji,","kad ih ljubim, cvijete mili,","prekratki su dani moji."],"en":["Gentle glances of your eyes","and your cheeks so soft and fine:","when I kiss them, darling flower,","all too short these days of mine."],"day":"04-21","occ_hr":"napisano na današnji dan, 2014.","occ_en":"written on this day in 2014"},{"slug":"sto-je-ljubav","title_hr":"Što je ljubav?","title_en":"What Is Love?","hr":["Ljubav je,","vjetrom nošen","lutajući brod,","koji muškarca vodi","u bračnu luku.","Kad progleda,","tek tada vidi","da je nasukan."],"en":["Love is","a drifting ship,","borne by the wind,","that carries a man","into wedlock's harbour.","When his eyes open,","only then does he see","that he has run aground."],"day":"04-22","occ_hr":"napisano na današnji dan, 1997.","occ_en":"written on this day in 1997"},{"slug":"puna-je-zivota","title_hr":"Puna je života","title_en":"She Is Full of Life","hr":["Puna je života","htjela bi da leti,","negdje u visine","u ljubavni ritam,","no, ipak joj smeta,","bračni zavjet sveti.","Ja joj djelić tuge","sa obraza čitam."],"en":["She is full of life,","she would love to fly","somewhere to the heights,","in love's rhythmic dance,","but it holds her back,","her holy marriage tie.","A small trace of grief","on her cheek meets my glance."],"day":"04-23"},{"slug":"sto-si-skrivila-generacijo","title_hr":"Što si skrivila generacijo?","title_en":"Generation, What Was Your Crime?","hr":["Jer životna zadnja mi je rata,","svetom Petru već kucam na vrata.","Pustite me da još malo živim,","pokoljenju svome da se divim."],"en":["My last instalment in this life I pay;","I'm knocking at Saint Peter's door today.","Just let me live a little longer, so","I may admire my offspring as they grow."],"day":"04-24"},{"slug":"opijelo-ljubavi","title_hr":"Opijelo ljubavi","title_en":"Requiem for Love","hr":["Zar je bilo dosta sretnoga života?","Zar me nikad više poljubiti neće?","Ona koju volim, što mi nosi sreće.","Zar je ljubav uvijek pomiješana plačem?","Kao koktel sreće, a najviše bola.","Zar se u ljubavi uvijek patit mora?"],"en":["Was that enough, then, of a life of happiness?","Will she never, never kiss me any more,","she whom I love, the joy that I am living for?","Is love forever mingled with our weeping,","like a cocktail mixed of joy, but mostly pain?","Must one who loves be made to suffer time and again?"],"day":"04-25"},{"slug":"oj-dodo-oj-dodole","title_hr":"Oj, dodo, oj, dodole","title_en":"Oj, Dodo, Oj, Dodole","hr":["Kome krivo, kome milo,","poreza je uvijek bilo,","nameta i raznih daća,","to je bilo od vajkada.","Al' za kišu da se plaća,","nije bilo baš nikada."],"en":["Some are sorry, some are glad,","taxes we have always had,","levies, dues of every kind,","so it's been since days of yore;","but to pay for rain, you'll find,","that was never done before."],"day":"04-26","occ_hr":"napisano na današnji dan, 1998.","occ_en":"written on this day in 1998"},{"slug":"imam-jedno-djevojce","title_hr":"Imam jedno djevojče","title_en":"I Have a Little Sweetheart","hr":["A kada je ne vidim,","tužan mi je svijet","jer bez njenog poljupca","ne miriše cvijet."],"en":["And when I cannot see her,","the world's a sad affair,","for, lacking her sweet kisses,","no flower scents the air."],"day":"04-27"},{"slug":"hrvatski-ponos","title_hr":"Hrvatski ponos","title_en":"Croatian Pride","hr":["Za oružje svoj novac sam dao,","trebalo je i nije mi žao.","Sa gorčinom srce mi se puni,","jer su novac uzeli tajkuni."],"en":["I gave my money for the arms we'd need;","it had to be, I don't regret the deed.","But now my heart is filled with bitter pain,","because tycoons have made that cash their gain."],"day":"04-28"},{"slug":"dravsko-proljece","title_hr":"Dravsko proljeće","title_en":"Drava Spring","hr":["Tridesetog travnja Sopje","spretno veze kolo sreće,","jer Sopjani toga dana","slave „DRAVSKO PRAMALJEĆE“."],"en":["On the thirtieth of April","Sopje weaves a joyful ring,","for upon that day its people","celebrate the \"Drava Spring\"."],"day":"04-29","occ_hr":"uoči Dravskog proljeća u Sopju","occ_en":"eve of the Drava Spring festival in Sopje"},{"slug":"sretan-ti-rodendan-sine","title_hr":"Sretan ti rođendan, sine!","title_en":"Happy Birthday, Son!","hr":["Ne saznao nikada za tugu.","Sve u sreći i bez bolnih rana,","s najdražima svoje obitelji,","proslavio mnogo rođendana."],"en":["May you never come to know of sorrow;","all in happiness, and free of pain,","with the dearest of your family","may you see many birthdays come again."],"day":"04-30","occ_hr":"Rođendan sina","occ_en":"His son's birthday"},{"slug":"lopata-i-kramp","title_hr":"Lopata i kramp","title_en":"The Shovel and the Pick","hr":["Lopata i stari kramp,","svakog dana složno rade:","zajednički cestu grade,","često puta trnje vade,","a ponekad ruže sade.","A sve rade bez nagrade!"],"en":["Shovel and the old pickaxe","work together every day:","build the road and pave the way,","often clear the thorns away,","and plant roses in the clay.","And they do it all without pay!"],"day":"05-01","occ_hr":"Praznik rada","occ_en":"Labour Day"},{"slug":"umirovljenicki-jadi","title_hr":"Umirovljenički jadi","title_en":"A Pensioner's Woes","hr":["Za tu Vladu starci su glasali,","da bi bolji standard uživali.","Kažem javno, neka je na znanje,","obećanje ludom radovanje."],"en":["The old folk voted this Government in,","so better living standards might begin.","I say it publicly, so all may hear:","a promise only makes the foolish cheer."],"day":"05-02"},{"slug":"ne-mogu-te-zaboraviti","title_hr":"Ne mogu te zaboraviti","title_en":"I Cannot Forget You","hr":["Ja nikada ne ću zaboravit moći,","sa tvojega lica kad pročitah sreću.","I nikada s drugom sretan biti ne ću,","kao s tobom svake provedene noći."],"en":["I never, ever shall be able to forget","the happiness that I could read upon your face;","and never with another woman in your place","be happy as with you on all the nights we met."],"day":"05-03"},{"slug":"vojnikova-majka","title_hr":"Vojnikova majka","title_en":"The Soldier's Mother","hr":["Muško sam čedo rodila,","njegovala ga i mazila.","Nad njim bdila i strepila,","u igri njegovoj,","uz osmijeh njegov","sretna sam bila."],"en":["I bore a son and held him tight,","I nursed and cuddled my delight,","kept watch and trembled through the night;","in his every game,","in his every smile,","my heart was light."],"day":"05-04"},{"slug":"osa","title_hr":"Osa","title_en":"The Wasp","hr":["Kao zumbul plavi","miriše joj kosa.","Ja sletoh na cvjetak","i postadoh osa."],"en":["Her hair has the scent","of a hyacinth blue;","I lit on the blossom,","and a wasp I grew."],"day":"05-05"},{"slug":"dug-dobili-bez-para-ostali","title_hr":"Dug dobili bez para ostali","title_en":"Debt Repaid, and Still No Money","hr":["Dok u Vladi moduse nalaze,","u blaženstva penzići odlaze.","Radili smo i zato smo krivi,","blago onom tko sve to preživi."],"en":["While in the Government they seek the ways,","the pensioners pass on to blissful days.","We worked, and so the guilty ones are we;","and lucky he who lives all this to see."],"day":"05-06"},{"slug":"kratki-dani","title_hr":"Kratki dani","title_en":"Short Days","hr":["Usne tvoje tople, meke,","kao perje ptice rajske.","U krilu se tvome topim,","k'o jutarnje rose majske."],"en":["Your warm lips are soft as feathers","of a bird of paradise;","in your lap I melt away","like the dew when May suns rise."],"day":"05-07"},{"slug":"san-o-sreci","title_hr":"San o sreći","title_en":"A Dream of Happiness","hr":["Budila me moja majka,","svako jutro zorimice","i suzama svojim toplim,","umivala moje lice."],"en":["My own mother used to wake me","every morning, at dawn's first trace,","and with her own tears, so warm,","she would wash my little face."],"day":"05-08"},{"slug":"klokan","title_hr":"Klokan","title_en":"The Kangaroo","hr":["Klokana nježnog, malog,","kad rujna zora zarudi,","dok u toploj torbi spava,","majčino srce budi."],"en":["The tender little kangaroo,","when the dawn is blushing red,","is woken by his mother's heart","sleeping in his warm pouch-bed."],"day":"05-09"},{"slug":"majka","title_hr":"Majka","title_en":"Mother","hr":["Za svaku bolest čeda svoga,","majčino srce pati.","Svoje bi oči za njega dala.","To može samo mati."],"en":["For each illness of her little one","a mother's heart aches through and through.","She would give her very eyes for it:","that, a mother alone can do."],"day":"05-10","occ_hr":"Majčin dan (svibanj)","occ_en":"Mother's Day (May)"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["I starost je polako već stigla,","barem da je zdravlje malo bolje.","Sada čekam na rajska blaženstva,","vjerujte mi, protiv svoje volje."],"en":["Old age has slowly come to me as well;","if only I were not so often ill!","Now I await the blessed joys of heaven —","believe me, friends, against my very will."],"day":"05-11","occ_hr":"Obljetnica pjesnikove smrti (2015.)","occ_en":"Anniversary of the poet's death (2015)"},{"slug":"nema-stiha","title_hr":"Nema stiha!","title_en":"No Verses!","hr":["Ja ne pišem pjesma više,","jer mi tuga grudi steže.","Ja ne pišem stiha više,","jer me bol uz krevet veže."],"en":["Poems I don't write any more,","sorrow weighs my breast like lead;","verses I don't write any more,","pain has tied me to my bed."],"day":"05-12"},{"slug":"sjecanje-na-djetinjstvo","title_hr":"Sjećanje na djetinjstvo","title_en":"Remembering My Childhood","hr":["Koru suhe prove svaki dan sam grizo.","Da se može bolje, nisam mog'o znati,","ipak nisam nikom u životu gmiz'o.","Tako me je moja naučila mati."],"en":["A crust of dry cornbread I gnawed on every day;","that life could be much better, I could never know,","yet all my life I've crawled to no one on my way:","and that is how my mother taught me, long ago."],"day":"05-13"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["Tu kolijevka stoji u buđaku,","dične ljude ona je zibala,","pokoljenja mnoga iznjedrila,","dok im majka pjesmicu pjevala."],"en":["The cradle stands there in its corner nook,","it rocked fine folk to sleep in days gone by,","brought forth so many generations, while","their mother sang to them a lullaby."],"day":"05-14"},{"slug":"netaknuta-ruza","title_hr":"Netaknuta ruža","title_en":"The Untouched Rose","hr":["Ili možda tvoje srce uzet neće.","To što nudi život, taj trenutak sreće.","Uzmi od života ono što je tvoje,","jer za sretnu ljubav trebaju tek dvoje."],"en":["Or maybe your own heart won't take what life extends:","that moment's happiness, the joy that fortune sends.","So take from life whatever's yours, whatever's due,","for happy love, my dear, all that it takes is two."],"day":"05-15"},{"slug":"lik-u-praznoj-casi","title_hr":"Lik u praznoj čaši","title_en":"A Face in the Empty Glass","hr":["Mjesto lica tvoga","ljubio sam čašu.","Pio rujno vino,","a ne tvoje usne.","Misleći na tebe","i na ljubav našu,","dok mi se na licu","topla suza gusne."],"en":["Instead of your face","I kissed only glass;","I drank the red wine","and not your sweet lips,","thinking of you only","and our love, alas,","while down my cheek slowly","a warm teardrop slips."],"day":"05-16"},{"slug":"od-djetinjstva-do-starackih-dana","title_hr":"Od djetinjstva do staračkih dana","title_en":"From Childhood to Old Age","hr":["Mili Bože, ima li što ljepše?","Kad se dvoje u ljubavi spoje,","pa kad krvca talasa k'o more,","a ti ne znaš gdje ti misli stoje."],"en":["Dear Lord, is there anything more lovely","than when two in love are joined as one,","and the blood goes surging like the sea,","and you don't know where your thoughts have run?"],"day":"05-17"},{"slug":"ljubav-nekada-i-sada","title_hr":"Ljubav nekada i sada","title_en":"Love Then and Now","hr":["Ali ta idila","trajala je kratko,","sve je brzo prošlo,","što je bilo slatko.","On se sada sjeća","prošlosti daleke,","nekadašnje ženice:","tihe, skromne, meke."],"en":["But that happy idyll","was over so fast;","all that was so sweet","was soon in the past.","Now he calls to mind","the far-off days gone by,","the little wife he had:","so quiet, soft and shy."],"day":"05-18"},{"slug":"hodi-mjesece-zvijezdama","title_hr":"Hodi, mjeseče, zvijezdama","title_en":"Walk, O Moon, Among the Stars","hr":["Hodi, mjeseče, zvijezdama,","potraži Danicu svoju.","Ugasi fenjer večeras,","dok ljubim voljenu moju."],"en":["Walk, O moon, among the stars,","seek your Danica, your own;","put your lantern out tonight","while I kiss my love alone."],"day":"05-19"},{"slug":"jeka","title_hr":"Jeka","title_en":"Echo","hr":["I zato što te volim","meni uvijek sude,","zbog ljubavi moje","i zbog pjesme lude."],"en":["And just because I love you","they judge me all day long,","for all this love of mine","and for my foolish song."],"day":"05-20"},{"slug":"pored-nase-rijeke","title_hr":"Pored naše rijeke","title_en":"Beside Our River","hr":["Od kada se nismo vidjeli nas dvoje?","Možda te sad više prepoznao ne bi'?","Godine su duge učinile svoje,","a nekada mio bio sam ja tebi."],"en":["How long since last we saw each other, we two?","Would I still know you now, if we should meet again?","The long years that have passed have done what years will do,","and once I used to be so dear to you, back then."],"day":"05-21"},{"slug":"starac","title_hr":"Starac!","title_en":"The Old Man","hr":["Udovi mi bolno hode","i to krhko nose tijelo.","Slabe oči što me vode,","a još bi se živjet htjelo."],"en":["Painfully my limbs still go,","bearing this frail frame along;","weak the eyes that guide me so,","yet the wish to live is strong."],"day":"05-22"},{"slug":"pijanica","title_hr":"Pijanica","title_en":"The Drunkard","hr":["Žena me je ostavila,","sve zbog rujna vina,","sa sobom je sve odnijela","i voljenog sina."],"en":["My wife has gone and left me,","all for the ruby wine;","she took everything with her,","and that dear son of mine."],"day":"05-23"},{"slug":"valpovo-nekada-i-sada","title_hr":"Valpovo nekada i sada","title_en":"Valpovo, Then and Now","hr":["Ne daj Bože da u noćno doba","neki momak pređe Karašicu,","bilo koji od ova dva roda,","da obiđe svoju vjerenicu!"],"en":["God forbid that, in the dead of night,","some lad across the Karašica went,","whichever of the two clans he was from,","to see his own betrothed, on courting bent!"],"day":"05-24"},{"slug":"pod-granama-jorgovana","title_hr":"Pod granama jorgovana","title_en":"Beneath the Lilac Boughs","hr":["Pod granama jorgovana,","u zvjezdanoj tihoj noći,","dok je ruža mirisala,","ljubio sam tvoje oči."],"en":["Underneath the lilac branches,","in the hush of starlit splendour,","while the rose was breathing fragrance,","your dear eyes I kissed so tender."],"day":"05-25"},{"slug":"dobro-dosli-prijatelji-dragi","title_hr":"Dobro došli prijatelji dragi!","title_en":"Welcome, My Dear Friends!","hr":["Svima vama, dragi moji hvala","što ste danas posjetili mene,","nema puno, vrijeme mi je kratko,","da se sklope moje oči snene."],"en":["Thank you all, my dear ones, every one,","that you came to visit me today;","not long now: the time I have is short","till my drowsy eyes are closed to stay."],"day":"05-26"},{"slug":"pitas-me","title_hr":"Pitaš me","title_en":"You Ask Me","hr":["Još da mogu da poljubim,","tvoja medna usta mala.","Vjeruj, dušo, da bi tada","moja pjesma sama cvala."],"en":["If, besides, I could but kiss","your small mouth, so honey-sweet,","trust me, darling, then my poem","of itself would bloom, complete."],"day":"05-27"},{"slug":"brodolomac","title_hr":"Brodolomac","title_en":"The Castaway","hr":["Da ti kažem hvala, ne, ja ipak ne ću,","ja ti dajem srce što za tobom žudi.","Ti si zaslužila radost još i veću","i poljupce slatke kada zora rudi."],"en":["To tell you \"thank you\"? No, I won't; I'll give you more:","my heart is what I give, the heart that longs for you.","You have deserved a joy still greater than before,","and sweetest kisses when the dawn comes blushing through."],"day":"05-28"},{"slug":"podravino-diko-moja","title_hr":"Podravino, diko moja","title_en":"Podravina, My Pride","hr":["Još te volim, rodni kraju,","meni treba ljubav tvoja.","Eh, da mogu prošlost vratiti,","Podravino, diko moja!"],"en":["Still I love you, native land,","and I need you by my side.","Ah, if I could bring the past back,","O Podravina, my pride!"],"day":"05-29"},{"slug":"hrvatski-ponos","title_hr":"Hrvatski ponos","title_en":"Croatian Pride","hr":["Ja sam Hrvat, to morate znati,","jer hrvatska rodila me mati","i sa svojim mlijekom nadojila,","u hrvatskom duhu odgajala."],"en":["I am a Croat, this you ought to know,","born of a Croat mother long ago;","and with her milk she nursed me as I grew,","and reared me in the Croatian spirit too."],"day":"05-30","occ_hr":"Dan državnosti","occ_en":"Statehood Day"},{"slug":"ljubav-se-ne-mjeri","title_hr":"Ljubav se ne mjeri","title_en":"Love Is Not Measured","hr":["Ne mogu ti reći koliko te volim,","jer se ljubav, dušo, ne mjeri aršinom.","Od ljubavi tvoje i tvog milovanja,","kao da sam sasvim opijen sa vinom."],"en":["I cannot tell you, darling, just how much I love you,","for love is not a thing a yardstick can define;","from all your love for me and all of your caresses,","it is as if I'm drunk, completely drunk, on wine."],"day":"05-31"},{"slug":"ima-li-sto-ljepse-od-djeteta","title_hr":"Ima li što ljepše od djeteta","title_en":"Is There Anything Lovelier Than a Child","hr":["Ima li što ljepše od djeteta,","tako nježnog, malenog stvora!?","Kada kraj tebe nespretno puzi,","kada ti guče umjesto govora."],"en":["Is anything more lovely than a child,","a creature so tender and so small!?","When clumsily it crawls beside you there,","when it just coos to you, with no words at all."],"day":"06-01","occ_hr":"Međunarodni dan djeteta","occ_en":"International Children's Day"},{"slug":"sjecanja","title_hr":"Sjećanja","title_en":"Memories","hr":["Željela si tada draga","da nikada ne svane dan,","da nam ljubav srca veže,","da vječito traje taj san."],"en":["Then, my darling, you were wishing","that the dawn would never break,","that our love would bind our hearts,","that from this dream we'd never wake."],"day":"06-02"},{"slug":"hrabra-budi","title_hr":"Hrabra budi","title_en":"Be Brave","hr":["Kada tebi netko bol nanese,","tada duša i mene zaboli.","To ne može drugačije biti,","jer moje te srce ludo voli."],"en":["When someone should cause you any pain,","then my soul, too, hurts along with you;","it could never be another way,","for my heart loves you madly, through and through."],"day":"06-03"},{"slug":"beliscanski-kotlic-mali","title_hr":"Belišćanski kotlić mali","title_en":"The Little Cauldron of Belišće","hr":["A radnička klasa, zna se,","oduvijek je složna bila,","pogotovo kad bi kakva","zabava se dogodila."],"en":["And the working class, we know,","always held together tight,","all the more if some occasion","for a party came in sight."],"day":"06-04","occ_hr":"napisano na današnji dan, 2005.","occ_en":"written on this day in 2005"},{"slug":"rastanak-s-vrticem","title_hr":"Rastanak s vrtićem","title_en":"Farewell to Kindergarten","hr":["Reći ću vam sada","jednu malu priču:","najljepše je nama","bilo u vrtiću.","Svu nježnost i pažnju","ovdje su nam dali,","pa i prvu ljubav","tu smo upoznali."],"en":["Let me tell you now","a story short and sweet:","our days in kindergarten","were the loveliest treat.","Their tenderness and care","they gave us all around,","and here our very first love","was also to be found!"],"day":"06-05"},{"slug":"volio-sam-tebe","title_hr":"Volio sam tebe","title_en":"I Loved You","hr":["Sada kada tebe nemam,","u sjećanju mome živiš.","Sada negdje u daljini,","ti se nekom drugom diviš."],"en":["Now that you are mine no more,","in my memory you live;","far away, to someone else","your admiring heart you give."],"day":"06-06"},{"slug":"presahle-suze","title_hr":"Presahle suze","title_en":"Dried-Up Tears","hr":["Gdje su nekad suze tekle,","tragovi su sada tamo.","A ljubav se rasplinula","ostala je tuga samo."],"en":["Where the tears once used to flow,","only traces now I see,","and our love has melted, faded;","only sorrow's left with me."],"day":"06-07"},{"slug":"probudi-se","title_hr":"Probudi se","title_en":"Wake Up","hr":["Probudi se!","Vrati se svome starom životu.","Dosta je bilo sreće i htjenja.","Zaključaj srce","i baci ključ u vodu,","tu kraj ovog starog kestenja."],"en":["Wake up!","Return now to the life you used to live.","Enough of happiness and longing's sway.","Lock up your heart","and throw the key into the water,","here, where the old chestnuts line the way."],"day":"06-08"},{"slug":"haiku","title_hr":"Haiku","title_en":"Haiku","hr":["OLUJA:","Oblaci plaču,","zvijezda vara mjeseca,","gromovi ječe."],"en":["Storm:","The clouds are weeping,","a star is cheating on the moon,","the thunders groan."],"day":"06-09"},{"slug":"sam","title_hr":"Sam!","title_en":"Alone!","hr":["Zvijezde već se gase,","novi dan se sprema,","tužno prolaze sati,","tebe, voljena, nema."],"en":["The stars are already fading,","a new day is breaking through;","sadly the hours go by,","and, my love, no sign of you."],"day":"06-10"},{"slug":"most-po-kome-gazis","title_hr":"Most po kome gaziš","title_en":"The Bridge You Walk Across","hr":["Mladost naša prolazi,","za podmladak živiš sad.","Starost brzo dolazi,","a s njome bol i jad.","Zato me miluj, draga,","poljupce daj mi sada.","Liječi mi srce bolno","i dušu punu jada."],"en":["Our youth is slipping past,","you live for the young today;","old age is coming fast,","with pain and grief to stay.","So caress me, darling,","give me kisses while you may;","heal this aching heart of mine","and my soul in its dismay."],"day":"06-11"},{"slug":"sto-mi-to-treba","title_hr":"Što mi to treba","title_en":"What Do I Need It For","hr":["Gledao sam njenu bračnu idilu:","voljeni joj glavu držaše u krilu","i nejačad onu brbljavu i milu,","tada srce svoje osjetih u bilu."],"en":["I saw her married idyll, happy as could be:","her loved one gently held her head upon his knee,","the little children, chattering, so sweet to see,","and then I felt my heart start pounding inside me."],"day":"06-12"},{"slug":"plavi-se-jadran-talasa","title_hr":"Plavi se Jadran talasa","title_en":"The Blue Adriatic Sways","hr":["Tko devize sobom nosi,","Jadranom se plavim kiti,","a naš radnik u snovima,","može more samo sniti."],"en":["Those who carry foreign money","wear the blue sea like a prize;","while our worker, in his dreaming,","sees the sea with sleeping eyes."],"day":"06-13"},{"slug":"zar-je-sve-to-bila-sala","title_hr":"Zar je sve to bila šala?","title_en":"Was It All Just a Joke?","hr":["Sjećaš li se one suze","što ti je iz oka pala?","Zar su to sve bile laži,","zar je sve to bila šala?"],"en":["Do you still recall the teardrop","that you shed in melancholy?","Was it nothing but a lie, then,","was it all a joke, a folly?"],"day":"06-14","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"pjesma-sinu","title_hr":"Pjesma sinu!","title_en":"A Poem for My Son!","hr":["Živio sam s tobom sretno svoju mladost.","Spavao si, sine, na mojim rukama.","U igri sa tobom dijelio sam radost.","Za bol tvoju ja sam bio na mukama."],"en":["I lived my youth with you, in happiness, my boy.","You slept, my son, so often in my arms at rest;","in playing with you, I would share in all your joy;","and when you were in pain, I suffered, sore distressed."],"day":"06-15","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"blago-meni-jer-me-majka-zeni","title_hr":"Blago meni, jer me majka ženi","title_en":"Lucky Me, My Mother's Marrying Me Off","hr":["Kao momak u Sopju sam bio,","ljepših cura, ja nisam vidio.","Preko dana žito sam vršio,","a navečer curice ljubio."],"en":["In Sopje, as a lad, I'll say outright:","no prettier girls had ever met my sight.","By day I threshed the wheat with all my might,","and kissed the little girlies every night."],"day":"06-16"},{"slug":"sokica","title_hr":"Šokica","title_en":"Šokica","hr":["Na polju je kao heroina,","kada srpom zlatno klasje žanje.","U posijelu uz kap rujnog vina,","svom je diki umiljato janje."],"en":["In the fields, a heroine so daring,","reaping golden grain, her sickle swinging;","at the sijelo, a wine-cup sharing,","to her darling, like a lamb, she's clinging."],"day":"06-17"},{"slug":"sokacki-obicaji","title_hr":"Šokački običaji","title_en":"Šokac Customs","hr":["Sada televizor zamjenjuje prela.","Sokaci su pusti, ne igra se kolo,","ni bećara nama da obiđu sijela.","Ničeg više nema, moj voljeni lolo!"],"en":["The television has now replaced the prela,","the lanes are deserted, none dances the kolo,","no bećars are left now to go round the sijela.","Nothing's left any more, my beloved lolo!"],"day":"06-18"},{"slug":"vojnikova-majka","title_hr":"Vojnikova majka","title_en":"The Soldier's Mother","hr":["Da odnijeti mogu","stručak cvijeća svježi.","Barem da znadem","gdje mu tijelo leži."],"en":["If only I could bring","fresh flowers, a small bouquet.","If only I knew","where his body lay."],"day":"06-19"},{"slug":"suha-kora-prove","title_hr":"Suha kora prove","title_en":"The Dry Crust of Cornbread","hr":["Kao dijete ja ne shvatih","među ljudstvom što se stvara,","da ne grize koru prove","onaj koji ima para."],"en":["As a child I did not see","how the ways of men unfold:","that the cornbread crust is never","gnawed by those who have the gold."],"day":"06-20"},{"slug":"slavonac-na-jadranu","title_hr":"Slavonac na Jadranu","title_en":"A Slavonian on the Adriatic","hr":["Poj sirena još odzvanja zrakom,","more šumi, vjetar ga talasa,","ljepše pjesme nisam nikad čuo,","do šuštanja zrelog žitnog klasa."],"en":["The sirens' song still echoes on the air,","the sea is stirred by wind, the waves resound;","a lovelier song I never yet have heard","than ripened wheat-ears rustling all around."],"day":"06-21"},{"slug":"kroz-valpovo-tece-karasica","title_hr":"Kroz Valpovo teče Karašica","title_en":"The Karašica Flows Through Valpovo","hr":["Kad je lipa šorom mirisala,","ljubav mi je Valpovčanka dala,","mjesečina nas je obasjala,","Karašica tiho proticala."],"en":["When linden scent along the lane would blow,","her love my Valpovo girl would then bestow;","the moon shone down on us with gentle glow,","and quietly the Karašica would flow."],"day":"06-22"},{"slug":"jos-sam-budan","title_hr":"Još sam budan","title_en":"Still Awake","hr":["Sa zvijezdama sjajnim","svoje želje snujem.","Da sam barem cvijetak,","na tvome prozoru."],"en":["Beneath the shining stars","I spin my dearest wishes:","were I a little flower","upon your window sill!"],"day":"06-23"},{"slug":"kad-ivanje-u-sopju-osvane","title_hr":"Kad Ivanje u Sopju osvane","title_en":"When St John's Day Dawns in Sopje","hr":["Bruji žica i vrisne Šokica,","preko Luke odjekne ravnica.","Ej, Sopjani, cvjetalo vam cvijeće","čekat ćemo Dravsko pramaljeće."],"en":["Strings are humming, and a Šokica cries,","over the Luka the whole plain replies.","Hey, Sopje folk, may flowers bloom each year!","We'll wait until the Drava Spring is here."],"day":"06-24","occ_hr":"Ivanje · napisano na današnji dan, 2012.","occ_en":"St John's Eve · written on this day in 2012"},{"slug":"diljem-slavonije","title_hr":"Diljem Slavonije","title_en":"All Across Slavonia","hr":["Eh što volim \"VALPOVAČKO LJETO\"!","Kad se skupi Šokadija mlada,","pa se kolo šorom zavijori,","a pod šat'rom svakojaka slada."],"en":["Eh, how I love the \"Valpovo Summer\"!","When young Šokadija gathers round,","and the kolo whirls along the lane,","and beneath the tent the treats abound."],"day":"06-25","occ_hr":"Valpovačko ljeto","occ_en":"Valpovo Summer festival"},{"slug":"ne-placi","title_hr":"Ne plači!","title_en":"Don't Cry!","hr":["Nasmiješi se malo kad si pokraj mene.","Da nam slatka ljubav kao rijeka teče.","Zaboravi tugu i te bolne sjene.","Neka bude više u životu sreće."],"en":["Smile a little bit whenever you're with me,","so that our love may, like a river, sweetly flow.","Forget the grief, those painful shadows: let them be,","and let more happiness come to us as we go."],"day":"06-26"},{"slug":"macak","title_hr":"Mačak","title_en":"The Tomcat","hr":["Eh, da mogu mačak biti,","makar i crn bio.","Rado bih se mladoj ženi,","ja u krilu svio."],"en":["Oh, if I could be a tomcat,","black, for all I care,","in a young wife's lap I'd gladly","curl up then and there."],"day":"06-27"},{"slug":"uspomena","title_hr":"Uspomena!","title_en":"A Memory!","hr":["A sada smo samo stranci.","Ni tvoj pogled neće mene.","A ljubavi više nema,","ostale su uspomene."],"en":["Now we're nothing more than strangers,","and your glance, too, shows disdain;","and the love is there no more;","only memories remain."],"day":"06-28"},{"slug":"cekao-sam-tebe","title_hr":"Čekao sam tebe!","title_en":"I Waited for You!","hr":["O, dođi mi, draga, ne preskači dane.","Poljupcima slatkim, vidaj moje rane.","Nježno kao čedo privini na grudi,","nikad nemoj poći, tu vječito budi."],"en":["O come to me, my darling, do not skip a day;","with your sweet kisses, dear, come heal my wounds, I pray;","and like a baby, hold me gently to your heart;","don't ever go away; stay here and never part."],"day":"06-29"},{"slug":"zaspalo-mace","title_hr":"Zaspalo mače","title_en":"The Sleeping Kitten","hr":["I kad spava, motor radi,","ona tiho prede.","Oh, te mačke baš ne znaju","gorivo da štede!"],"en":["Even sleeping, motor running,","purring soft and deep.","Oh, these cats just never learn","fuel isn't cheap!"],"day":"06-30"},{"slug":"domovino-moja","title_hr":"Domovino moja","title_en":"My Homeland","hr":["Slavonijo, zemljo ponosita,","malo ravna, malo bregovita,","zlatnim klasjem ti si okićena","i sa rujnim vinom zalivena."],"en":["O Slavonia, land so proud and fair,","somewhat flat, and hilly here and there,","decked in golden ears of wheat, you shine,","watered well with ruby-coloured wine."],"day":"07-01"},{"slug":"sreca","title_hr":"Sreća","title_en":"Happiness","hr":["Kada se srcem ljubi,","radosnog te zora budi.","Kad ispuni sreća grudi,","cijeli svijet se tada ljubi."],"en":["When with all your heart you love,","dawn will wake you, glad and blessed;","when true joy has filled your breast,","then the whole wide world's in love."],"day":"07-02"},{"slug":"beracica-cvijeca","title_hr":"Beračica cvijeća","title_en":"The Flower Gatherer","hr":["Ali vjetar sudbe pirne sa planine,","k'o latice nježne raznese joj sreću.","Još jedino čujem vapaj iz daljine","i znam da je više nikad vidjet ne ću."],"en":["But then the wind of fate comes gusting from the hill","and scatters all her joy, as tender petals fall;","and only from afar a cry comes to me still,","and I know I shall never see her more at all."],"day":"07-03","occ_hr":"napisano na današnji dan, 1977.","occ_en":"written on this day in 1977"},{"slug":"ribar","title_hr":"Ribar","title_en":"The Fisherman","hr":["Kad se kući vrati","mokar i bez ribe,","naveliko svoje","on raspreda priče.","Avaj, bolni jade","jedna mi otpade.","Pet kila je bila!","Ushićeno kliče!"],"en":["When he's back, at last,","soaking wet, no fish,","at great length, and grandly,","he spins tales to the skies:","\"Alas, oh bitter woe,","one got away! Oh no!","Five kilos, it weighed in!\"","he cries with shining eyes."],"day":"07-04"},{"slug":"plavi-se-jadran-talasa","title_hr":"Plavi se Jadran talasa","title_en":"The Blue Adriatic Sways","hr":["Ljetno sunce morem žeže.","Hoteli su stalno puni,","a na plaži dupe griju,","samo stranci i tajkuni."],"en":["Summer sun scorches the sea,","the hotels are full year-round,","and on beaches, warming bums,","only strangers and tycoons are found."],"day":"07-05","occ_hr":"napisano na današnji dan, 1985.","occ_en":"written on this day in 1985"},{"slug":"zora-te-meni-u-zagrljaj-vraca","title_hr":"Zora te meni u zagrljaj vraća","title_en":"Dawn Brings You Back into My Arms","hr":["Mi se gubimo u oblaku sreće,","noć mi je tada blažena i kraća,","a zlatnim zracima veselu, sretnu,","zora te meni u zagrljaj vraća."],"en":["We lose ourselves within a cloud of joy;","my night grows short then, blissful in its charms,","and, glad and happy, on its golden rays,","my love, the dawn brings you back into my arms."],"day":"07-06","occ_hr":"napisano na današnji dan, 1983.","occ_en":"written on this day in 1983"},{"slug":"trac","title_hr":"Trač","title_en":"Gossip","hr":["Kakvo je to sad nastalo vrijeme?","Svatko može na svakog da viče.","Što ja radim, što se koga tiče.","Neka svatko nosi svoje breme."],"en":["What's this time that's come to us today?","Anyone can shout at anyone.","What I do: whose business? Surely none.","Let each bear his burden on his way."],"day":"07-07"},{"slug":"dodi-voljena","title_hr":"Dođi voljena","title_en":"Come, My Beloved","hr":["Dođi i onda","kada sam tužan,","srce te moje","i onda želi."],"en":["Come to me also","when I am grieving,","for this heart of mine","longs to have you near."],"day":"07-08"},{"slug":"moja-velika-otkrica","title_hr":"Moja velika otkrića","title_en":"My Great Discoveries","hr":["Kad sam bio mali","činio sam čuda.","Gdje god nije trebalo","bilo me je svuda."],"en":["When I was a small boy,","I worked wonders all around;","wherever I shouldn't be,","there I could be found!"],"day":"07-09"},{"slug":"presahle-suze","title_hr":"Presahle suze","title_en":"Dried-Up Tears","hr":["Pri susretu našem sada,","tužan osmijeh licem prođe,","kao grč od nekog bola","uspomena davna dođe."],"en":["Now, whenever we two meet,","a sad smile will pass and die;","like the spasm of some pain","comes a memory long gone by."],"day":"07-10"},{"slug":"moje-ce-te-oci-oplakati","title_hr":"Moje će te oči oplakati!","title_en":"My Eyes Will Weep for You!","hr":["Zato pođi, ja ti želim zbogom.","Moje će te oči oplakati.","U mislima ja ću biti s tobom.","Što ja nisam, drugi će ti dati."],"en":["So go, then; I will bid you now farewell.","My eyes will weep for you, and tears will flow.","In all my thoughts with you I'll always dwell.","What I did not, another will bestow."],"day":"07-11"},{"slug":"ispod-stare-lipe","title_hr":"Ispod stare lipe","title_en":"Beneath the Old Linden","hr":["Kad bi stara lipa","ispričati znala,","sve poljupce slatke","koje si mi dala."],"en":["If the old linden","could tell, if it knew,","of all the sweet kisses","that I had from you."],"day":"07-12","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["Ali vrijeme prođe kao jeka,","sve sa sobom u zaborav nosi,","zlatno klasje sada kombajn žanje,","žitnog zrnja puni su silosi."],"en":["But time goes by the way an echo goes,","and takes it all, forgotten, on its way;","the combine reaps the golden ears of wheat,","the silos now are full of grain today."],"day":"07-13"},{"slug":"sto-si-skrivila-generacijo","title_hr":"Što si skrivila generacijo?","title_en":"Generation, What Was Your Crime?","hr":["Kad izbrojih što mi poštar dao,","od tuge sam skoro zaplakao,","a od bola postala mi muka","i staračka zadrhtala ruka.","Radio sam četrdeset ljeta,","da postanem socijalna bijeda."],"en":["When I had counted what the postman brought,","I nearly wept for sorrow at the thought,","and from the pain I felt sick through and through,","and my old hand began to tremble too.","I've worked for forty summers, just to be","a welfare case, reduced to misery."],"day":"07-14"},{"slug":"ja-obicni-smrtnik","title_hr":"Ja obični smrtnik!","title_en":"I, an Ordinary Mortal!","hr":["Oh, božice moja!","Kakav sam ja drznik.","Kada te sa svetog","pijedestala skidam,","u naručje svoje.","Ja obični smrtnik."],"en":["What a daring man I am,","oh, my goddess, my immortal,","when from your holy pedestal","I lift you down this way","into my arms:","I, an ordinary mortal."],"day":"07-15","occ_hr":"napisano na današnji dan, 1983.","occ_en":"written on this day in 1983"},{"slug":"pjesma-sinu","title_hr":"Pjesma sinu!","title_en":"A Poem for My Son!","hr":["Sa tobom je bilo mnogo sretnih dana,","a još više strepnjom probdivenih noći.","Zato nikad, sine, nikad ne dozvoli,","da ranjenom dušom u grob moram poći."],"en":["With you, my son, there have been many happy days,","and more, the nights I lay awake in dread and fear.","So never, son, oh never, never let it be","that with a wounded soul I'm carried to my bier."],"day":"07-16"},{"slug":"prija","title_hr":"Prija","title_en":"My Prija","hr":["Nakon druge, treće čaše,","jezici se razvezaše.","Sve smo lijepo ispričali,","o rodbini što smo znali","i novosti koje ima,","što se priča u gostima.","Bilo je to baš veselo,","pretresli smo cijelo selo."],"en":["By the second glass, the third,","tongues were loosened, word by word.","All of it we talked right through:","all about our kin we knew,","and whatever news was out,","what the guests all talk about.","It was merry, such a treat:","we combed the village, street by street."],"day":"07-17","occ_hr":"napisano na današnji dan, 1997.","occ_en":"written on this day in 1997"},{"slug":"vrati-mi-snove","title_hr":"Vrati mi snove!","title_en":"Give Me Back My Dreams!","hr":["A noći su hladne,","oh, kako su duge!","Jer na sebi tvoje,","ne osjećam ruke."],"en":["And the nights are cold,","oh, the nights are long!","For I cannot feel","your arms where they belong."],"day":"07-18"},{"slug":"sismis-ili-mis","title_hr":"Šišmiš ili miš","title_en":"Flittermouse or Mouse","hr":["Bio jedan šišmiš","koji je izgubio šiš,","pa je postao miš.","Šišmiš","minus","šiš,","jednako","miš!"],"en":["Once there lived a flittermouse","who lost his flitter in the house,","and so became a mouse.","Flittermouse","minus","flitter","equals","mouse!"],"day":"07-19"},{"slug":"ne-krivi-mene","title_hr":"Ne krivi mene","title_en":"Don't Blame Me","hr":["Ne krivi mene što te žarko ljubim,","ni srce moje što za tebe bije.","Bez ljubavi tvoje ja nadu gubim.","Bez smijeha tvoga, draga, tužno mi je."],"en":["Don't blame me that I love you with such fire,","nor blame my heart that beats for you so true;","without your love, all of my hopes expire,","without your laughter, darling, I am blue."],"day":"07-20"},{"slug":"slavonac-na-jadranu","title_hr":"Slavonac na Jadranu","title_en":"A Slavonian on the Adriatic","hr":["Skitao sam po Jadranu plavom,","od Rovinja do čuvenog Splita,","ali nigdje ja vidio nisam,","ljepšeg mora do slavonskog žita."],"en":["Along the blue Adriatic I've roamed,","from Rovinj down to famous Split, my feet","have carried me, but nowhere have I seen","a fairer sea than our Slavonian wheat."],"day":"07-21"},{"slug":"puzic-i-kucica","title_hr":"Pužić i kućica","title_en":"The Little Snail and His House","hr":["Odgovara pužić:","\"Meni teška nije,","ljeti imam hlada,","a zimi me grije.\"","Pitale ga gliste","što se tako vuče:","\"Mogu kako hoću,","kod svoje sam kuće!\""],"en":["The little snail replies:","\"It's not heavy for me:","in summer I have shade,","in winter, warm I'll be.\"","The earthworms asked him why","he dragged along so slow:","\"I do just as I please,","I'm home wherever I go!\""],"day":"07-22"},{"slug":"vatre-na-konjari","title_hr":"Vatre na konjari","title_en":"Bonfires on the Konjara","hr":["Nekada davno u ono staro doba,","dok su konji bili prvoklasna roba.","Svaku noć bi konje napasali ljudi,","U zvjezdanoj noći, dok mjesec zarudi."],"en":["Long, long ago, back in the days of old,","when horses were first-class goods, bought and sold,","each night the people grazed their horses, led","out under stars, as the moon rose, glowing red."],"day":"07-23","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"zov-domovine","title_hr":"Zov domovine","title_en":"The Call of the Homeland","hr":["Zato svoju zemlju i ljubi i voli,","najdražom je zovi, vrijeđat ne dozvoli.","Ona ti sve prašta, k'o rođena mati.","Tu rođenu grudu treba čuvat znati."],"en":["So love your land, and cherish her, and hold her dear;","call her the dearest one, let no insult come near.","She forgives all, just like the mother of your birth;","you must know how to keep and guard your native earth."],"day":"07-24"},{"slug":"hodi-mjesece-zvijezdama","title_hr":"Hodi, mjeseče, zvijezdama","title_en":"Walk, O Moon, Among the Stars","hr":["Molim te, mjeseče sjajni,","ne svijetli ove noći,","kad poljubim dragu moju,","ti možeš opet doći."],"en":["Shining moon, I beg you, please,","do not shine for us tonight;","when I've kissed my darling, then","you may come back into sight."],"day":"07-25","occ_hr":"napisano na današnji dan, 1989.","occ_en":"written on this day in 1989"},{"slug":"volio-bih-da-sam-vjetar","title_hr":"Volio bih da sam vjetar","title_en":"I Wish I Were the Wind","hr":["Oh, da mogu biti vjetar!","Koliko li za me sreće?","Poljupcima prije snova,","sklapao bih dragoj vjeđe."],"en":["If I only were the wind, oh!","What a joy I would be reaping!","Kissing her before she slumbers,","I would close her eyes for sleeping."],"day":"07-26"},{"slug":"dobro-dosli-prijatelji-dragi","title_hr":"Dobro došli prijatelji dragi!","title_en":"Welcome, My Dear Friends!","hr":["To je bilo trideset i treće,","u mjesecu kad se žito želo,","dvajs'devetog, a bio je petak,","pa sam svakoj radosti početak."],"en":["It was in the year of thirty-three,","in the month when they were reaping wheat,","the twenty-ninth, and Friday was the day,","so every joy begins with me, I say."],"day":"07-27","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"na-dan-vjencanja","title_hr":"Na dan vjenčanja!","title_en":"On Your Wedding Day!","hr":["U životu mome sve si bio meni,","za tebe bih dao obje svoje ruke.","Od ovoga trena ti pripadaš ženi,","ja ti želim sreću, bez bola i muke."],"en":["You have been my everything throughout my life;","for your sake I would give both my hands away;","From this moment on, you belong to your wife;","I wish you joy, without pain or torment on your way."],"day":"07-28","occ_hr":"napisano na današnji dan, 1979.","occ_en":"written on this day in 1979"},{"slug":"poezijski-rad-kroz-zivot","title_hr":"Poezijski rad kroz život","title_en":"A Life's Work in Poetry","hr":["Ivan Benak mi je ime,","pjesnik koji piše rime.","Još od mojih školskih dana,","poezija mi je hrana.","","Šezdeset je ljeta prošlo,","od kada sam napisao:","„NE BUDI ME, MAJKO, RANO,","JOŠ SE NISAM NASPAVAO“.","","I starački došli dani,","nema zdravlja kao prije,","ali srce moje gordo,","ukrotila starost nije.","","I još nešto važno ima,","reći ću vam sada svima.","Od preksutra svako veče',","SEDAMDESET OSMA TEČE!"],"en":["Ivan Benak is my name,","poet: rhyming is my aim.","Since my days at school began,","poetry has fed this man.","","Sixty summers now have passed","since I wrote, so long ago:","\"MOTHER, DO NOT WAKE ME EARLY,","I AM NOT YET RESTED, NO.\"","","Now the days of age are here,","and my health is not the same,","yet my heart, as proud as ever,","age has never learned to tame.","","Something else important, too,","I will now tell all of you:","two days hence, as night draws near,","starts my SEVENTY-EIGHTH YEAR!"],"day":"07-29","special":"birthday","sig_hr":"Valpovo, 18. 07. 2010.","sig_en":"Valpovo, July 18, 2010","occ_hr":"Pjesnikov rođendan (1933.)","occ_en":"The poet's birthday (1933)"},{"slug":"dodi-na-moje-grudi","title_hr":"Dođi na moje grudi","title_en":"Come and Lie Upon My Breast","hr":["Kada prođe cvijet mladosti","i starost polako se nudi,","da nađeš ljubav kao žena,","dođi na moje grudi!"],"en":["When the flower of youth has faded","and old age steals in, a guest,","so you'll find love as a woman,","come and lie upon my breast!"],"day":"07-30"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["Lijepu mladost armiji sam dao,","vratili me kad se želo polje.","Još se nisam naljubio cura,","ožene me, i bez moje volje."],"en":["I gave my lovely youth to army life;","they sent me home at harvest time; and still","I hadn't had my fill of courting girls:","they married me, and that without my will."],"day":"07-31"},{"slug":"ti-voljena-zeno","title_hr":"Ti voljena ženo","title_en":"You, Beloved Woman","hr":["Ona mala klupa,","kad sam cjelov krao!","To mirisno sijeno,","gdje si ljubav dala","i zvjezdice sjajne,","kad sam ljubav dao!...","Naš su nijemi svjedok.","Ti voljena ženo!"],"en":["That little bench there,","where I stole a kiss so sweet!","And that fragrant hay,","where you gave your love,","and the shining stars,","when I gave my love complete!...","are our silent witness.","You, beloved woman!"],"day":"08-01"},{"slug":"pokloni-mi-draga","title_hr":"Pokloni mi, draga","title_en":"Give Me, My Darling","hr":["Podaj meni tugu,","tvoje bolne duše,","da bol tvoju, draga,","s tobom podijelim."],"en":["Give to me the sorrow","of your aching soul,","so your pain, my darling,","may be shared by two."],"day":"08-02"},{"slug":"nikad-vise","title_hr":"Nikad više!","title_en":"Never More!","hr":["Nikad više neću reći:","Mila, ludo, volim tebe!","Koliko te stvarno volim,","zadržat ću to za sebe."],"en":["Never more will I be saying:","\"Darling, madly I love you!\"","How much love for you I carry,","that I'll keep and hide from view."],"day":"08-03","occ_hr":"napisano na današnji dan, 1985.","occ_en":"written on this day in 1985"},{"slug":"etno-kuca-semialjac-kate","title_hr":"Etno kuća Semialjac Kate","title_en":"Kata Semialjac's Ethno House","hr":["Štala prazna, nema više konja,","plug drveni i ornice stoje,","vjetrenjača u štaglju miruje,","vremena su učinila svoje."],"en":["The stable's empty, there's no horse at all,","the wooden plough and ploughing gear stand still,","the winnowing machine rests in the barn:","the times have done their work, as all times will."],"day":"08-04"},{"slug":"rodena-gruda","title_hr":"Rođena gruda","title_en":"Native Soil","hr":["Najljepše je uvijek na rođenoj grudi","i zemljica ova što te kruhom hrani.","Tu si se rodio, tu živi i budi.","Ne daj domovinu, s ljubavlju je brani."],"en":["It's always loveliest within your native land,","and this dear little earth that gives you bread each day.","Here you were born; so live here, here take up your stand.","Don't give your homeland up; with love, keep foes away."],"day":"08-05","occ_hr":"Dan pobjede i domovinske zahvalnosti","occ_en":"Victory and Homeland Thanksgiving Day"},{"slug":"jucer-digla-baka","title_hr":"Jučer digla baka","title_en":"Yesterday Grandma Held Her Head High","hr":["Što bi sada ona","da unuka nema?","Ostala bi baka","u kući da drijema."],"en":["What would Granny do","with no grandchild there?","She'd just stay at home,","dozing in her chair."],"day":"08-06"},{"slug":"rodendan-ti-sretan-zelim-franjo","title_hr":"Rođendan ti sretan želim Franjo!","title_en":"A Happy Birthday to You, Franjo!","hr":["Kroz Tvoj život nek' se ljubav kreće,","u tvom radu Bog Ti dao sreće,","na Tvom putu cvjetalo Ti cvijeće,","jer nam život bez povratka teče."],"en":["Through all your life may love go where you go,","and in your work may God His luck bestow,","along your path may flowers bloom and grow,","for life flows on, and back it cannot flow."],"day":"08-07"},{"slug":"hrabra-budi","title_hr":"Hrabra budi","title_en":"Be Brave","hr":["Kada mora iz snova te budi,","kada tuga razara ti grudi,","kada netko zbog ljubavi sudi,","ti ne plači, nego hrabra budi."],"en":["When a nightmare wakes you from your rest,","when your sorrow tears apart your breast,","when someone condemns the love you've confessed,","do not cry: be brave, and stand the test."],"day":"08-08","occ_hr":"napisano na današnji dan, 1987.","occ_en":"written on this day in 1987"},{"slug":"ugodno-druzenje-umirovljenika","title_hr":"Ugodno druženje umirovljenika","title_en":"A Pleasant Pensioners' Get-Together","hr":["Veselo je, hvala dragom Bogu,","zaigraše kolo, tango, polku,","nek se vidi što PENZIĆI mogu,","sutra ćemo misliti na boljku."],"en":["It's merry, thanks be to the Lord above;","they danced the kolo, tango, polka too;","let all now see what OLDIES are made of:","tomorrow we'll give aches a thought or two."],"day":"08-09"},{"slug":"uslisi-me-boze","title_hr":"Usliši me, Bože","title_en":"Hear Me, O God","hr":["Hoću li, Bože, i ja u raj?","To iskreno želim, ali se bojim.","U raju će biti slava i sjaj,","a ja Ti na lošem glasu stojim."],"en":["Shall I too, O God, to heaven go?","I truly wish it, yet I live in fear.","In heaven there'll be glory, splendour's glow,","and my good name with You is poor down here."],"day":"08-10"},{"slug":"postarica-u-penziji","title_hr":"Poštarica u penziji","title_en":"The Retired Postwoman","hr":["Na tekućem u poštanskoj,","mirovina mala.","Da se vrati bivšem radu,","ne zna što bi dala.","Al' već druga mlada žena,","sa poslom se sladi.","Došla starost, bol se javlja,","sretna što ne radi."],"en":["In her postal bank account","there's a pension, small;","to go back to her old job","she would give her all.","But a younger woman now","finds the work a treat;","age has come, and aches are showing:","she's glad to quit her beat."],"day":"08-11"},{"slug":"opijelo-ljubavi","title_hr":"Opijelo ljubavi","title_en":"Requiem for Love","hr":["Zašto uvijek pišem na kraju života?","A preskačem sreću onih prvih dana,","dok još srce nije bilo puno rana?"],"en":["Why do I always write when life is at its end,","and skip the joy of those first days, right at the start,","when there were not yet many wounds upon my heart?"],"day":"08-12"},{"slug":"uloga-zene-u-braku","title_hr":"Uloga žene u braku","title_en":"A Wife's Role in Marriage","hr":["Kada na kraju u krevet dođe,","da odmori umornu dušu","i tada treba nježna da bude,","da pruži ljubav mužu."],"en":["When at the end of day she comes to bed,","so she can rest her weary soul and frame,","then, even then, she must be soft and tender","and love her husband all the same."],"day":"08-13"},{"slug":"posljednji-cjelov","title_hr":"Posljednji cjelov","title_en":"The Last Kiss","hr":["Oh, kako je sada tiho oko mene:","ni poj ptica više ne čujem k'o prije.","Od ljubavi naše ostale su sjene!","U srcu mi čemer k'o u kotlu vrije."],"en":["Oh, how silent everything is now for me:","I hear the birds no more the way I used to do.","Of all our love, it's only shadows that I see!","My heart's a cauldron where the bitter sorrows brew."],"day":"08-14"},{"slug":"bol-kroz-zivot","title_hr":"Bol kroz život","title_en":"A Lifetime of Pain","hr":["Ponekad se teško hodi,","neravni su često puti,","kroz život me sudba vodi.","Ti uz mene, Gospo, budi!"],"en":["Sometimes it is hard to tread,","often rugged is the way;","through my life by fate I'm led:","Lady, stay by me, I pray!"],"day":"08-15","occ_hr":"Velika Gospa","occ_en":"Assumption Day"},{"slug":"prica-o-muji-i-fati","title_hr":"Priča o Muji i Fati","title_en":"The Tale of Mujo and Fata","hr":["Al' samoća dušu truje,","mladost traži želje svoje,","a noći su puste, duge,","ljepši život je u dvoje."],"en":["Loneliness, though, poisons souls,","youth has longings of its own,","and the nights are long and empty:","life is sweeter not alone."],"day":"08-16","occ_hr":"napisano na današnji dan, 2004. (inačica „Storija o Mati i Kati“)","occ_en":"written on this day in 2004 (the version “The Story of Mata and Kata”)"},{"slug":"zelene-su-oci-tvoje","title_hr":"Zelene su oči tvoje","title_en":"Green Are Those Eyes of Yours","hr":["Zašto kažeš da me voliš,","kada lažno grliš mene?","I dok mučiš srce moje,","moja mladost tužno vene."],"en":["Why then tell me that you love me,","when you hold me, just pretending?","While you torture me with heartache,","all my youth in grief I'm spending."],"day":"08-17"},{"slug":"dao-sam-ti-boli","title_hr":"Dao sam ti boli","title_en":"I Gave You Pain","hr":["Nježnost sam ti htio dati.","Moje te srce još voli.","Umjesto ljubavi moje,","ja tebi sam dao boli."],"en":["Tenderness I meant to give you,","and my heart still loves you so.","But instead of my affection,","all I gave to you was woe."],"day":"08-18"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["Pod orahom djeda kosu kuje,","baka užad plete pokraj kuće.","Miris kruha dvorištem se širi,","bit će danas i pogače vruće."],"en":["Beneath the walnut Grandpa peens his scythe,","and Grandma plaits her ropes beside the wall;","the smell of bread is spreading through the yard,","today there'll be hot flatbread for us all."],"day":"08-19","occ_hr":"napisano na današnji dan, 2006.","occ_en":"written on this day in 2006"},{"slug":"ljubav-se-ne-mjeri","title_hr":"Ljubav se ne mjeri","title_en":"Love Is Not Measured","hr":["Nikad neću žalit' što sam te ljubio.","Za tvoju sam ljubav tebi svoju dao.","Da se opet rodim, opet bih tvoj bio","i na grudi tvoje sav sretan bih pao."],"en":["I'll never feel regret that I have loved you so;","for all your love I gave you mine, I gave it all;","and were I born again, I'd still be yours, I know,","upon your breast, in perfect happiness, I'd fall."],"day":"08-20"},{"slug":"kratki-dani","title_hr":"Kratki dani","title_en":"Short Days","hr":["Kad mi nježni cjelov daješ","i šapućeš nježno, mili,","pijanstvo mi glavom prođe,","kao vino da smo pili."],"en":["When you give me tender kisses,","whisper softly, \"Darling mine,\"","then my head goes light and reeling","as if we had drunk of wine."],"day":"08-21"},{"slug":"haiku","title_hr":"Haiku","title_en":"Haiku","hr":["SVITANJE:","Mjesec se gasi,","pijetao kljuca zoru,","miriše jutro."],"en":["Dawn:","The moon is fading,","a rooster pecks at the dawn,","the morning's fragrant."],"day":"08-22"},{"slug":"postovani-josipe","title_hr":"Poštovani Josipe!","title_en":"Dear Josip!","hr":["Život bez povratka","polako teče,","po stazama trnje","tek poneko cvijeće."],"en":["Life without return","flows along so slow;","thorns along the paths,","and few flowers grow."],"day":"08-23","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"zov-domovine","title_hr":"Zov domovine","title_en":"The Call of the Homeland","hr":["U tuđoj se zemlji gorka sjeta krije.","Jednom ćeš se vratit, ako nikad prije,","ono u starost, kad mladost uvene,","da posiješ kosti u utrobe njene."],"en":["In foreign lands a bitter sorrow lies in wait;","one day you will come back, if not before, then late:","in old age, when your youth has withered all away,","to sow your bones within her womb, and there to stay."],"day":"08-24"},{"slug":"skromnost","title_hr":"Skromnost!","title_en":"Modesty!","hr":["Ja ne želim biti,","ni heroj u boju,","već želim tebe","i ljubav tvoju."],"en":["I don't wish to be","a hero in the war;","I want only you","and your love, nothing more."],"day":"08-25"},{"slug":"suha-kora-prove","title_hr":"Suha kora prove","title_en":"The Dry Crust of Cornbread","hr":["U snovima bijelog kruha,","svježu krišku ja sam snio,","a na javi koru prove","suzama sam natopio."],"en":["In my dreams I used to dream","of a fresh white slice of bread,","but awake, the cornbread crust","I would soak with tears instead."],"day":"08-26"},{"slug":"hodi-mjesece-zvijezdama","title_hr":"Hodi, mjeseče, zvijezdama","title_en":"Walk, O Moon, Among the Stars","hr":["Zasjao mjesec srebrni,","svud viri taj bećar stari,","gleda nježno milovanja","i druge ljubavne stvari."],"en":["Now the silver moon shines out;","peeping everywhere above,","that old bećar eyes caresses","and the other things of love."],"day":"08-27"},{"slug":"nard-je-selo-sto-ga-ljubi-drava","title_hr":"Nard je selo što ga ljubi Drava","title_en":"Nard Is the Village the Drava Kisses","hr":["Na tamburi kada cikne žica,","odjekuje Slavonska ravnica."],"en":["When the tambura string rings sharp and high,","Slavonia's plain resounds in reply."],"day":"08-28"},{"slug":"ne-pitam-te","title_hr":"Ne pitam te","title_en":"I Don't Ask You","hr":["Ne pitam te gdje si jučer bila.","Ja ne pitam gdje ćeš sutra biti,","ni sa kim si noćas snove snila,","ni za kim ćeš sutra suze liti."],"en":["I don't ask you where you were yesterday,","nor where you will be upon the morrow,","nor with whom last night you dreamed away,","nor for whom you'll shed your tears in sorrow."],"day":"08-29","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"volim-ljubav","title_hr":"Volim ljubav","title_en":"I Love Love","hr":["Mladost bješe kratka","na ovome svijetu.","Zato ljubljah žene","u najljepšem cvijetu."],"en":["Youth upon this earth","lasted but an hour;","so I kissed the women","in their fairest flower."],"day":"08-30"},{"slug":"sva-godisnja-doba","title_hr":"Sva godišnja doba","title_en":"All the Seasons","hr":["Za mene je bilo i suviše slatko.","Želio sam tebe, tvoje zagrljaje.","A naše je ljeto bilo vrlo kratko.","Oh, kako sam htio da vječito traje!"],"en":["For me it was all sweet, and even far too sweet;","I longed for you, and for your arms around me, dear.","And yet our summer was so short, so very fleet;","oh, how I wished that it would last, year after year!"],"day":"08-31"},{"slug":"mala-skola","title_hr":"Mala škola","title_en":"The Little School","hr":["Nakon ljetnog ferja","jesen će nam doći,","tada će u pravu","školu oni poći.","S velikom torbom,","u njoj školske knjige","i njihove tajne,","radosti i brige."],"en":["After summer break","autumn will come round,","and then to real school","they will all be bound,","with a great big satchel","packed with books, all new,","and their little secrets,","joys and worries too."],"day":"09-01"},{"slug":"zena","title_hr":"Žena","title_en":"Woman","hr":["Što je žena,","Kakva je uloga njena?","Žena je san,","Lijepa k'o sunčan dan."],"en":["Woman: what is she?","What is her role to be?","A woman is a dream,","lovely as a sunbeam."],"day":"09-02"},{"slug":"ne-mogu-te-zaboraviti","title_hr":"Ne mogu te zaboraviti","title_en":"I Cannot Forget You","hr":["Nikada te ne ću zaboravit moći.","Divna, nasmijana tvoja usta medna,","što bijahu mojih poljubaca žedna,","ni predivne tvoje umiljate oči."],"en":["I never, ever shall be able to forget","your lovely, laughing mouth, with all its honey sweet,","that thirsted for my kisses every time we'd meet,","nor those endearing eyes of yours, the loveliest yet."],"day":"09-03"},{"slug":"zeni-za-rodendan","title_hr":"Ženi za rođendan","title_en":"To My Wife on Her Birthday","hr":["Na tom putu što me pratiš,","od svega ti srca hvala!","A dvoje si divne djece,","meni, dušo, darovala."],"en":["For the road you've walked beside me,","all my heartfelt thanks are due!","And two lovely children, darling,","were the gift I had from you."],"day":"09-04","occ_hr":"Rođendan supruge Jelke","occ_en":"His wife Jelka's birthday"},{"slug":"skolska-torba","title_hr":"Školska torba","title_en":"The School Bag","hr":["Nije teška, vjerujte,","svi je đaci nose,","a znanja je prepuna","kao cvijeće rose."],"en":["It's not heavy, honestly,","every pupil bears it too,","and it's brimming full of knowledge","like the flowers full of dew."],"day":"09-05","occ_hr":"Početak škole","occ_en":"First day of school"},{"slug":"nek-se-slavi-u-sopju-veselje","title_hr":"Nek' se slavi u Sopju veselje","title_en":"Let Sopje Celebrate and Make Merry","hr":["Sve dok bude bilo Slavonije,","skupljat će se Šokadija naša","i veselja bit će kao prije,","uz tambure dobrih tamburaša."],"en":["For as long as Slavonia stays,","our Šokadija will gather still,","there'll be merriment as in old days,","with tamburas played by men of skill."],"day":"09-06","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"smrt-starog-hrasta","title_hr":"Smrt starog hrasta","title_en":"Death of the Old Oak","hr":["Bio jednom stari hrast,","u Valpovu pokraj pruge,","godine je tu brojio,","mnoge zime hladne, duge.","Dva stoljeća preživio,","mnoge vlade promijenio,","tri je rata pretrpio,","nevremenu prkosio."],"en":["Once there stood an old oak tree","in Valpovo by the rails;","there he counted up his years,","many winters' icy gales.","Through two centuries he'd grown,","saw regimes be overthrown,","three wars' hardship he had known,","and through storms he held his own."],"day":"09-07"},{"slug":"destinacije-opcine-sopja","title_hr":"Destinacije općine Sopja","title_en":"Destinations of Sopje Municipality","hr":["Ritska Ada tu je nekad bila,","pjesnika je ona iznjedrila.","Još je ovdje, samo što se skriva,","pjesnikovo još djetinjstvo sniva."],"en":["Here, long ago, was Ritska Ada's place;","it brought the poet forth from its embrace.","It is still here, only hidden away,","and the poet's childhood dreams there to this day."],"day":"09-08","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"andreji-za-22-rodendan","title_hr":"Andreji za 22. rođendan","title_en":"To Andreja on Her 22nd Birthday","hr":["Andrejice unučice,","draga naša golubice.","I još jedno ljeto prođe,","tvoj rođendan dragi dođe."],"en":["Andreja, our grandchild dear,","our sweet dove, whom we hold near,","one more summer's slipped away,","your dear birthday's here today."],"day":"09-09","occ_hr":"Rođendan unuke Andreje","occ_en":"His granddaughter Andreja's birthday"},{"slug":"godine-po-zelji","title_hr":"Godine po želji","title_en":"Years to Order","hr":["Kao u stara dobra vremena,","dok je još Bog hodao po zemlji.","Sa Olimpa Eros dobrostivo veli:","Zbor penzioneri, mladost se dijeli.","Koliko tko godina sada želi?"],"en":["Just as in the good old times, the days of yore,","when the Lord still walked about upon the earth,","from Olympus, Eros kindly had his say:","\"Pensioners, fall in! Youth's being given away!","How many years does each one want today?\""],"day":"09-10"},{"slug":"zivot-penzionera","title_hr":"Život penzionera","title_en":"A Pensioner's Life","hr":["Još jedino pred izbore,","sve partije nas se sjete.","Obećanja, prazne fraze,","sa svih strana pljušte, lete."],"en":["Only just before elections","do the parties call us friend;","promises and empty phrases","pour and fly from end to end."],"day":"09-11"},{"slug":"kritika","title_hr":"Kritika","title_en":"Criticism","hr":["Jednog dana mi reče,","kritičar strog i ljut,","da pjesme ne pišem više,","da pero bacim u kut.","Meni kad želje se jave,","k'o jesenje guste kiše,","u ruci pero se nađe","i samo pjesme piše."],"en":["One day a critic told me,","with a stern and angry look,","that I should write poems no more","and throw my pen in a nook.","But when my longings gather","like autumn's heavy rain,","a pen turns up in my hand","and just writes poems again."],"day":"09-12"},{"slug":"lastavica","title_hr":"Lastavica","title_en":"The Swallow","hr":["Kada dođe jesen,","srce me zazebe.","S odlaskom svojim","stvaraš meni sjetu.","Išao bih s tobom","u tople krajeve,","ali krila nemam","da letim po svijetu."],"en":["When the autumn comes,","my heart starts to freeze;","as you fly away,","you leave me sad and blue.","I'd go with you, swallow,","to warm lands overseas,","but I have no wings","to fly the whole world through."],"day":"09-13"},{"slug":"jos-postoji-nada","title_hr":"Još postoji nada","title_en":"There Is Still Hope","hr":["Još postoji nada","da mi snove budiš,","još postoji nada","da mi ljubav vratiš,","još postoji nada","da me nježno ljubiš.","U ljubavi našoj,","da me vjerno pratiš."],"en":["There's hope for us yet","my dreams you'll renew,","there's hope for us yet","you'll love me once more,","there's hope for us yet","you'll kiss me, soft and true,","and, side by side in love,","stay faithful as before."],"day":"09-14","occ_hr":"napisano na današnji dan, 1982.","occ_en":"written on this day in 1982"},{"slug":"uspomena","title_hr":"Uspomena!","title_en":"A Memory!","hr":["Ja se često sjetim tebe,","i ljubavi naše žarke.","Da li je to ljubav bila","ili tvoje spretne varke?"],"en":["Often I remember you","and our love that burned so bright.","Was it love, what we both had,","or your artful, clever sleight?"],"day":"09-15"},{"slug":"televizor-prodajem-u-boji","title_hr":"Televizor prodajem u boji","title_en":"Colour TV for Sale","hr":["Na TV-u prava utakmica,","pokraj tebe sjela i ženica,","sretna guče, puna dobre volje.","Pa zar može nešto biti bolje?"],"en":["A proper match is on the screen tonight,","your little wife sits by you, snug and tight;","she's cooing, happy, in the best of cheer:","could anything be better? Not round here!"],"day":"09-16"},{"slug":"skolska-torba","title_hr":"Školska torba","title_en":"The School Bag","hr":["S odličnim bi uspjehom","prošla škola svaka,","kad bi torba odgovor","dala mjesto đaka."],"en":["Every school would pass with honours,","every single one,","if the school bag gave the answers","and the pupils none."],"day":"09-17"},{"slug":"dva-potoka-dvije-rijeke","title_hr":"Dva potoka, dvije rijeke","title_en":"Two Streams, Two Rivers","hr":["I sad dvije rijeke teku,","ravnim poljem krivudaju.","Ukrasne su to tkanice,","što nam krase Slavoniju."],"en":["And two rivers now are flowing,","winding over level ground;","they are festive, woven sashes","that adorn Slavonia round."],"day":"09-18"},{"slug":"ljubav-nekada-i-sada","title_hr":"Ljubav nekada i sada","title_en":"Love Then and Now","hr":["A kada ga ugleda,","pogleda ga mrko.","Od pogleda njezinog,","već je na pol crko."],"en":["And when she lays eyes on him,","she gives him a grim glare;","and from that look of hers","he's half dead then and there."],"day":"09-19"},{"slug":"od-djetinjstva-do-starackih-dana","title_hr":"Od djetinjstva do staračkih dana","title_en":"From Childhood to Old Age","hr":["Kad se sjetim svojega djetinjstva","i mladosti što je sretno došla.","U životu Amorovih strijela,","kroz srce mi na stotine prošla."],"en":["When I think back on my childhood days","and my youth, so happy from the start,","all my life, by hundreds, Amor's arrows","have gone flying straight on through my heart."],"day":"09-20"},{"slug":"sretan-ti-rodendan-denise","title_hr":"Sretan ti rođendan Denise","title_en":"Happy Birthday, Denis","hr":["Dajemo ti dara","ovo malo para,","to ti daje djeda","i voljena baka,","da bi među nama","bila ljubav jaka."],"en":["We give you a gift, dear:","a little cash here;","it comes from your Grandpa","and dear Grandma too,","so that between us","love grows strong and true."],"day":"09-21","occ_hr":"Rođendan unuka Denisa","occ_en":"His grandson Denis's birthday"},{"slug":"sjecanje-na-djetinjstvo","title_hr":"Sjećanje na djetinjstvo","title_en":"Remembering My Childhood","hr":["Djetinjstvo moje bolno mi prisjelo.","Svakoga sam dana bos po trnju hodo.","Na meni je bilo skrpljeno odijelo,","dok sam tuđe krave po strnjaku vodo."],"en":["My childhood weighs on me, a bitter pain I've known:","barefoot I walked on thorns, and did so every day;","the clothes upon my back were patched and roughly sewn,","while I led other people's cows where stubble lay."],"day":"09-22"},{"slug":"hvala-ti-draga","title_hr":"Hvala ti, draga!","title_en":"Thank You, Darling!","hr":["Još su oči tvoje, mila, pune čežnje,","a riječi su tople, iskrene i nježne.","Oh, ljubavi moja, na svemu ti hvala."],"en":["Still full of longing are those eyes of yours, my dear,","and all your words are warm and tender and sincere.","Oh, love of mine, for everything I give you thanks."],"day":"09-23","occ_hr":"napisano na današnji dan, 1973.","occ_en":"written on this day in 1973"},{"slug":"presahle-suze","title_hr":"Presahle suze","title_en":"Dried-Up Tears","hr":["Presahle su suze sreće,","sa izvora oka moga.","Od ljubavi ostala je","bolna rana srca moga."],"en":["Dried up are the tears of gladness","at the wellspring of my eyes.","All that's left me of our loving:","in my heart a sore wound lies."],"day":"09-24"},{"slug":"radosno-djetinjstvo","title_hr":"Radosno djetinjstvo","title_en":"Happy Childhood","hr":["Igraju se i pjevaju,","tu na djecu tete paze,","djeci pjesme tu čitaju","i tete ih divno maze.","U igri im nema kraja,","to je dio pravog raja."],"en":["Here they play and here they sing,","and the aunties mind them there;","read them rhymes of everything,","and they cuddle them with care.","There's no end to all their play,","it's a piece of heaven, I'd say."],"day":"09-25"},{"slug":"sretan-ti-rodendan","title_hr":"Sretan ti rođendan","title_en":"Happy Birthday to You","hr":["Znaj na tome svijetu ima","netko tko te silno voli.","Bez ljubavi tvoje, draga,","u grudima nosi boli."],"en":["Know that somewhere in this world","there is one who loves you so,","who, without your love, my darling,","in his breast bears pain and woe."],"day":"09-26"},{"slug":"sumski-kralj","title_hr":"Šumski kralj","title_en":"The Forest King","hr":["Što je to:","u šumi živi","šumski kralj,","ima djece milijun,","sva mu djeca","kapu nose,","a samo je","nema on."],"en":["What is this:","in the woods there lives","the forest king,","with a million young about;","all his children","wear a cap,","only he","goes without."],"day":"09-27"},{"slug":"0-5-promila","title_hr":"0.5 promila","title_en":"0.5 Per Mille","hr":["Radi naših mladenaca,","da bi svadba lijepa bila,","vratite nam stari zakon,","bar na nula-pet promila!"],"en":["For the sake of our young couples,","so each wedding's lovely still,","give us back the law we had:","at least zero point five per mille!"],"day":"09-28"},{"slug":"dolazak-zime","title_hr":"Dolazak zime","title_en":"The Coming of Winter","hr":["Jesenje kiše tjeraju ljeto,","lišće polako žuti.","Po cesti vjetar prašinu diže","i huči – valjda se ljuti."],"en":["The autumn rains are driving summer out,","the leaves turn slowly yellow;","along the road the wind whips up the dust","and howls: perhaps he's cross, the fellow."],"day":"09-29","occ_hr":"Miholje","occ_en":"Michaelmas"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["Godine su učinile svoje,","kičma mi se savila na dolje.","Od života osta uspomena,","sve je prošla, protiv moje volje."],"en":["The years have done their work, as years must do;","my spine is bent, and bends down lower still.","Of life there's nothing left but memory:","it all went by, and quite against my will."],"day":"09-30"},{"slug":"draga-nasa-unucice","title_hr":"Draga naša unučice!","title_en":"Our Dear Little Granddaughter!","hr":["Draga naša unučice!","Sve najbolje što sad znamo,","rođendan ti čestitamo!","Pa makar si sada snaša,","unuka si ipak naša."],"en":["Our dear little granddaughter!","All the best that we can say:","happy birthday to you today!","Even though you're now a wife,","you're our granddaughter for life."],"day":"10-01","occ_hr":"Rođendan unuke Željke","occ_en":"His granddaughter Željka's birthday"},{"slug":"da-spasimo-stare-obicaje","title_hr":"Da spasimo stare običaje","title_en":"Let Us Save the Old Customs","hr":["Ujesen bi ljudi kukuruze brali,","uz vino i pjesmu doma komušali.","Skupila se moba, veseli su bili,","a dečki bi cure doma otpratili."],"en":["In the autumn they would pick the maize and bring","all the cobs back home to husk, with wine, and sing.","A moba would gather, merry, every one,","and the lads would walk the girls home when all was done."],"day":"10-02"},{"slug":"zena","title_hr":"Žena","title_en":"Woman","hr":["Žena je nježno ljubila,","Mnoge je bogove rodila.","Zvijezde trepere","U njenoj kosi,","U bujnim njedrima","Mjesec skriva.","Na krhkim plećima","Planetu nosi.","I bit će voljena","Sve dok je živa."],"en":["Woman's love was tender, mild;","many a god has been her child.","Stars are twinkling","in her hair,","in her full bosom's fold","she hides the moon from view.","Her fragile shoulders hold","the planet in her care.","And loved she'll be","her whole life through."],"day":"10-03"},{"slug":"pjesnicka-zadovoljstva","title_hr":"Pjesnička zadovoljstva","title_en":"The Poets' Pleasures","hr":["Sa svih strana dične Slavonije,","svojoj duši pjesnik maštu dade:","O ljepoti, o bolu, o ratu,","netko ljubav, netko svoje jade."],"en":["From every side of proud Slavonia","the poet let his soul's own fancy flow:","of beauty, and of pain, and of the war,","one wrote of love, and one his grief and woe."],"day":"10-04"},{"slug":"sto-je-najbrze","title_hr":"Što je najbrže","title_en":"What Is Fastest?","hr":["\"Najbrže su, djeco, misli,","one se baš svega sjete.\"","Mudro reče nastavnica:","\"Misli među zvijezde lete.\""],"en":["\"Fastest, children, are our thoughts,","they can think of anything,\"","wisely then the teacher said.","\"Up among the stars they wing.\""],"day":"10-05","occ_hr":"Dan učitelja","occ_en":"Teachers' Day"},{"slug":"sokica","title_hr":"Šokica","title_en":"Šokica","hr":["Poljupcima prekrivam joj lice,","najljepše je u moje Šokice.","Ej Šokice, milo moje janje,","na jesen te vodim na vjenčanje."],"en":["I will kiss the face that all surpasses,","fairest face of all the Šokac lasses.","Hey, Šokica, my sweet lamb, I'm bringing","you to wed when autumn bells are ringing!"],"day":"10-06"},{"slug":"hrabra-budi","title_hr":"Hrabra budi","title_en":"Be Brave","hr":["Da bol tvoju podijelim, dozvoli,","kad sam radost, sad mogu i tugu,","tvoja rana i mene zaboli,","nikada neću zavoljeti drugu."],"en":["Let me share the pain that you go through;","since I shared your joy, your grief I'll bear;","every wound of yours will hurt me too;","I'll love no other woman anywhere."],"day":"10-07"},{"slug":"dva-potoka-dvije-rijeke","title_hr":"Dva potoka, dvije rijeke","title_en":"Two Streams, Two Rivers","hr":["Brzim tokom niz planinu,","jedne jako hladne zime,","u žurbi je mali potok","izgubio svoje ime.","U dolini smirio se.","Da l' zbog hira ili vica","stanovnici toga kraja","nazvaše ga Karašica."],"en":["Rushing swiftly down the mountain,","one hard winter, bitter cold,","in its haste the little streamlet","lost the name it had of old.","In the valley it grew calm;","whether as a whim or joke,","Karašica it was named","by the local country folk."],"day":"10-08"},{"slug":"ja-i-moj-medas-josip","title_hr":"Ja i moj međaš Josip","title_en":"Me and My Neighbour Josip","hr":["U tom svemu ipak nešto smeta,","sad brojimo časno višak ljeta.","Nikada nam nije bilo bolje:","u raj ćemo protiv svoje volje!"],"en":["In all of this, though, one thing's in the way:","we count, with honour, extra years today.","It has never been so good for us, and still,","off to paradise against our will!"],"day":"10-09"},{"slug":"etno-kuca-zelcin","title_hr":"Etno kuća Zelčin","title_en":"The Ethno House at Zelčin","hr":["Štagalj prazan, miris sijena sanja,","vrisak konja još nosi u duši,","a pljevara na njeg naslonjena,","od starosti polako se ruši."],"en":["The empty barn dreams of the smell of hay,","still bears the horses' whinny in its soul;","the chaff-shed, leaning up against its side,","is crumbling slowly, old, no longer whole."],"day":"10-10"},{"slug":"zov-domovine","title_hr":"Zov domovine","title_en":"The Call of the Homeland","hr":["Rođena ti gruda sreću, ljubav daje,","svako drvo, kamen, dječje radovanje.","To ti tuđa zemlja nikad neće dati.","Maćeha se majkom nikad neće zvati."],"en":["The soil where you were born gives you both love and joy,","each tree, each stone, and all the gladness of a boy;","no foreign land will ever give you this, no other:","a stepmother will never bear the name of mother."],"day":"10-11"},{"slug":"ne-pitam-te","title_hr":"Ne pitam te","title_en":"I Don't Ask You","hr":["Ja se pitam do sad bila gdje si,","da za tebe jučer nisam znao.","Volim tebe takvu kakva jesi,","takvu sam te, mila, upoznao."],"en":["I ask myself where you have been till now,","that until yesterday I never knew you.","I love you as you are, for that is how,","just like that, my dear, I came to know you."],"day":"10-12"},{"slug":"godine-po-zelji","title_hr":"Godine po želji","title_en":"Years to Order","hr":["Vidi Bog ljubavi o čemu se radi,","da starcima malo patnju osladi,","on pusti glazbu, a vino poteče","i ljubav se vodila čitavu veče.","U to sa istoka zlatna zora sine","i staračke snove u maglu raspline."],"en":["The god of love saw what it was about,","and to sweeten old folks' pain, he helped them out:","he let the music play, the wine flow free,","and all the evening, love was made with glee.","Then from the east the golden dawn shone through,","and melted old folks' dreams to mist and dew."],"day":"10-13","occ_hr":"napisano na današnji dan, 1997.","occ_en":"written on this day in 1997"},{"slug":"neposlusni-vrabac","title_hr":"Neposlušni vrabac","title_en":"The Disobedient Sparrow","hr":["U ovoj priči ima","nešto vrjednije od zlata:","nije vam svatko prijatelj","tko vas vadi iz blata."],"en":["In this story there's a lesson","worth more gold than you could spend:","not all those who pull you out","of the mud will be your friend."],"day":"10-14"},{"slug":"zivot-penzionera","title_hr":"Život penzionera","title_en":"A Pensioner's Life","hr":["Penzioner svakog dana","pismonošu željno čeka.","Za nagradu svome radu","što je rint'o pola vijeka.","Cijelo vrijeme mašta, sanja,","što će moći sve da kupi.","\"Kupit ću si drva sada,","dok još zima ne nastupi.\""],"en":["Every day the pensioner","waits for when the postman's due:","his reward for all the slaving","half a century right through.","All the time he dreams and muses","what he'll buy, the things he'll get:","\"Now I'll buy myself some firewood,","while the winter's not here yet.\""],"day":"10-15"},{"slug":"zasto-covjek-nije-kao-dijete","title_hr":"Zašto čovjek nije kao dijete","title_en":"Why Is Man Not Like a Child","hr":["Zašto čovjek nije kao dijete","što koru kruha među sobom dijeli?","Zašto mnogi zemaljsko blago","samo za sebe želi?"],"en":["Why is man not like a child","that will share its crust of bread with all its friends?","Why do many want earth's riches","only for their selfish ends?"],"day":"10-16","occ_hr":"Svjetski dan kruha · napisano na današnji dan, 1975.","occ_en":"World Bread Day · written on this day in 1975"},{"slug":"brodolomac","title_hr":"Brodolomac","title_en":"The Castaway","hr":["Sudbina je htjela da mi ruke pružiš,","onoga trenutka, kada tonu lađe.","Da sam opet voljen i da žarko ljubim","od toga saznanja ništa nije slađe."],"en":["Then fate decreed that you should reach your hands to me","the very moment when the ships sink down below.","That I am loved again, and ardently in love:","there's nothing sweeter than the knowledge that it's so."],"day":"10-17"},{"slug":"sada-smo-stranci","title_hr":"Sada smo stranci!","title_en":"Now We Are Strangers!","hr":["Zar da kunem sudbu što sam te ljubio?","Meni ova patnja bolnu dušu para.","Na grudima tvojim ja sam snove snio.","A sada smo stranci, to mi boli stvara."],"en":["Shall I then curse my fate for having loved you so?","This suffering now tears my aching soul apart.","Upon your breast I dreamed my dreams not long ago,","and now we're strangers, and that's what breaks my heart."],"day":"10-18","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"sva-godisnja-doba","title_hr":"Sva godišnja doba","title_en":"All the Seasons","hr":["U ljubavi našoj sve do ovih dana.","Sva godišnja doba prošla su kroz mene.","Od najljepše sreće pa do bolnih rana.","Od žarkoga ljeta do zime studene."],"en":["In our love, up to these days, right from the start,","all the seasons of the year through me have rolled:","from the sweetest joy to wounds that ache and smart,","from the burning summer to the winter's cold."],"day":"10-19","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"volim-te-lavicu","title_hr":"Volim te laviću","title_en":"I Love You, Little Lion","hr":["Koliko si puta,","draga, meni rekla:","volim te laviću!","Dok je Drava tekla."],"en":["How often, my darling,","you told me, you'd say:","\"I love you, little lion!\"","while the Drava flowed away."],"day":"10-20","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"sto-je-drvo","title_hr":"Što je drvo","title_en":"What Is a Tree?","hr":["Na granama lista lišće,","što ga nježni lahor njiše,","a to su mu, dijete, pluća,","ono kao i ti diše."],"en":["On the branches leaves come out,","which the gentle breeze blows through,","and, my child, these are its lungs:","it breathes just the way you do."],"day":"10-21"},{"slug":"ja-volim-nadu","title_hr":"Ja volim Nadu","title_en":"I Love Nada","hr":["Vjerujete mi, dečki,","nisam više dijete.","Ja volim Nadu","iz klupe pete!"],"en":["Believe me now, fellows,","I'm not a kid, I repeat:","I love Nada","from the fifth seat!"],"day":"10-22"},{"slug":"most-po-kome-gazis","title_hr":"Most po kome gaziš","title_en":"The Bridge You Walk Across","hr":["Ne zaboravi da vrijeme leti","i za sobom ostavlja trag.","Mladosti naše tada se sjeti","i bit ću ti ponovno drag."],"en":["Don't forget how swiftly time will fly,","leaving all its trace behind;","then remember how our youth went by,","and once more I'll be dear, you'll find."],"day":"10-23"},{"slug":"pjesma-valpovu","title_hr":"Pjesma Valpovu","title_en":"A Poem for Valpovo","hr":["Dođe jesen i lišće uvene,","dani kratki, a noć je velika.","Kada mi se sklope oči snene,","Valpovo je opet meni dika."],"en":["Autumn comes, the leaves fade, one and all,","days are short, the nights are long and deep;","when at last my sleepy eyelids fall,","Valpovo remains my pride in sleep."],"day":"10-24"},{"slug":"beracica-cvijeca","title_hr":"Beračica cvijeća","title_en":"The Flower Gatherer","hr":["Dok je tako sretna svoje snove snila","i gledala milo biće koje voli,","sa zapada zlatna rumen se razlila.","Da je vječno tako, tiho Boga moli."],"en":["And while so happily she dreamed her gentle dreams","and gazed upon the dear one whom her heart adored,","a golden glow spilled from the west in rosy streams;","she prays in silence: \"Let it last for ever, Lord.\""],"day":"10-25"},{"slug":"uloga-zene-u-braku","title_hr":"Uloga žene u braku","title_en":"A Wife's Role in Marriage","hr":["Žena treba muža da voli","i djecu nježno mazi.","Za njene nitko ne pita boli:","tko još na to da pazi!"],"en":["The wife should love her man with all her heart","and pet the children small;","but no one asks her where her own pains smart:","who heeds such things at all!"],"day":"10-26"},{"slug":"odgovor-drenovcanke","title_hr":"Odgovor Drenovčanke","title_en":"The Drenovci Woman's Reply","hr":["Nema više divnih snova,","ostala mi pusta želja.","Sada želim od života,","samo jednu kap veselja."],"en":["No more lovely dreams are left,","empty wishing lingers here;","now all that I want from life","is a single drop of cheer."],"day":"10-27"},{"slug":"sam","title_hr":"Sam!","title_en":"Alone!","hr":["Sam uz šapat vjetra,","na prošle mislim dane.","Sam u kasnoj noći,","bolujem svoje rane."],"en":["Alone with the whispering wind,","I think of the days now flown.","Alone, late into the night,","I nurse the wounds I've known."],"day":"10-28"},{"slug":"bol-kroz-zivot","title_hr":"Bol kroz život","title_en":"A Lifetime of Pain","hr":["Ljudima si puno puta,","u pomoći, Gospo, bila,","iako si i ti gorke,","na svom putu suze lila!"],"en":["Many times you've helped, Our Lady,","people in their pain and fears,","though you too along your journey","shed your own most bitter tears!"],"day":"10-29"},{"slug":"ne-cekaj-me","title_hr":"Ne čekaj me","title_en":"Don't Wait for Me","hr":["Uspomene naše","zadržat ću za se.","I nikada više","ja ti doći neću."],"en":["And all our memories","I'll keep for me alone.","And never any more","to you will I return."],"day":"10-30"},{"slug":"uslisi-me-boze","title_hr":"Usliši me, Bože","title_en":"Hear Me, O God","hr":["Možda ima kakav skromni kutić","i to je, Bože, dovoljno za me.","Stisnut ću se kao suhi prutić,","usko je moje staračko rame."],"en":["Perhaps there is some corner, not too big,","and that, O God, would be enough for me.","I'll squeeze in there, as thin as a dry twig:","my aged shoulder's narrow as can be."],"day":"10-31"},{"slug":"pjesnikova-zelja-1983","title_hr":"Pjesnikova želja","title_en":"The Poet's Wish","hr":["Jednom kada odem","u rajska blaženstva","ponekada dođi,","moj grob obiđi."],"en":["Some day, when I've gone","to the bliss of heaven,","now and then, come round,","visit where I lie."],"day":"11-01","occ_hr":"Svi sveti","occ_en":"All Saints' Day","note_hr":"Ivan Benak počiva na valpovačkom groblju.","note_en":"Ivan Benak rests in the Valpovo cemetery.","note_url":"https://www.google.com/maps/search/?api=1&query=45.669460%2C18.401563"},{"slug":"najdrazima-ja-darujem-dusu","title_hr":"Najdražima ja darujem dušu","title_en":"To My Dearest I Give My Soul","hr":["Prošao je život kao jeka","i odnio dio naših snova.","Najdražima, obitelji mojoj,","nek' im radost pruži knjiga ova."],"en":["Like an echo, life has passed and gone,","and has carried part of our dreams away.","To the ones I love most, my family,","may this book bring gladness every day."],"day":"11-02","occ_hr":"Dušni dan","occ_en":"All Souls' Day"},{"slug":"anice","title_hr":"Anice","title_en":"To Anica","hr":["Ovaj život kao rijeka teče","i odnosi dio naših snova.","Kap veselja od srca ti želim,","tvojoj sreći i ja se veselim."],"en":["This life of ours flows onward like a river","and carries off a portion of our dreams.","From all my heart, a drop of joy for you:","your happiness will make me happy too."],"day":"11-03"},{"slug":"sve-dane-moje","title_hr":"Sve dane moje","title_en":"All My Days","hr":["Sve dane moje radosti,","tebi sam, draga, dao.","Najljepšu snagu mladosti,","no, ipak mi nije žao."],"en":["All my days of joy and cheer","I have given all to you,","my youth's finest strength, my dear,","yet it's nothing that I rue."],"day":"11-04"},{"slug":"posljednji-cjelov","title_hr":"Posljednji cjelov","title_en":"The Last Kiss","hr":["Kroz moj bolni život ti si prošetala.","Poljupcima vrelim rane si vidala.","Milujući tebe sreća mi je sjala,","sada sa mog neba zvijezda je nestala."],"en":["Through my life of pain you strolled along your way;","with burning kisses you would heal my wounds each day;","caressing you, my joy shone bright as the sun's ray;","now from my sky a star has vanished clean away."],"day":"11-05"},{"slug":"kratki-dani","title_hr":"Kratki dani","title_en":"Short Days","hr":["Vječito ćeš moja biti,","to, voljena, moraš znati.","U jesen ću pred oltarom","zlatni prsten tebi dati."],"en":["You will be forever mine,","this, beloved, you must know:","at the altar, come the autumn,","a gold ring I will bestow."],"day":"11-06"},{"slug":"postarica","title_hr":"Poštarica","title_en":"The Post-Office Girl","hr":["A ona mi moj pogled uzvrati.","Divan osmijeh s anđeoskog lica,","pa mi marku za pismo naplati.","Baš je divno zvanje poštarica!"],"en":["And she looks right back at me, the way I do,","from her angel's face a lovely smile displayed,","then she charges me the postage that is due.","What a lovely calling is the post-girl's trade!"],"day":"11-07","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"dao-sam-ti-boli","title_hr":"Dao sam ti boli","title_en":"I Gave You Pain","hr":["Kazni me, odbaci, prezri","i to bih sve prebolio,","no, nikada nemoj reći,","da nisam te ludo volio."],"en":["Punish, cast me off, and scorn me:","all of that I could live through;","but you must not ever say","that I did not madly love you."],"day":"11-08"},{"slug":"san-o-sreci","title_hr":"San o sreći","title_en":"A Dream of Happiness","hr":["A ja malen još nejačak,","daleki sam snio sanak.","U mašti sam sretan bio,","a na javi plaćo danak."],"en":["And I, little, weak, each day","dreamed a dream of far away.","In my fancies I was happy,","but awake, I had to pay."],"day":"11-09"},{"slug":"zenske-suze","title_hr":"Ženske suze!","title_en":"A Woman's Tears!","hr":["I opet tuga","radost mi uze,","jer popih,","tople, tužne i guste,","ženske suze."],"en":["And once again sorrow","stole the joy of my years,","for I drank,","warm and sad and thick,","a woman's tears."],"day":"11-10"},{"slug":"kad-kocije-zasviraju","title_hr":"Kad Kočije zasviraju","title_en":"When Kočije Strike Up","hr":["Kad Martinje kaže svoje,","pravo vino je u čaši.","A „KOČIJE“ tada poje:","„DOBRO VINO TAMBURAŠI“!"],"en":["When St Martin has his say,","real wine's in the glass again;","then Kočije sing away:","“Good Wine, You Tambura Men!”"],"day":"11-11","occ_hr":"Martinje · napisano na današnji dan, 2014.","occ_en":"St Martin's Day · written on this day in 2014"},{"slug":"suzani-za-rodendan","title_hr":"Suzani za rođendan","title_en":"For Suzana's Birthday","hr":["Za tren oka nestalo djetinjstvo,","u nepovrat otišli su snovi.","Kćeri mila, od srca ti želim,","da ti budu sretni dani novi."],"en":["In a blink your childhood disappeared,","and your dreams have gone, not to return.","Dearest daughter, from my heart I wish","that new happy days be yours in turn."],"day":"11-12","occ_hr":"Rođendan kćeri Suzane","occ_en":"His daughter Suzana's birthday"},{"slug":"zov-domovine","title_hr":"Zov domovine","title_en":"The Call of the Homeland","hr":["Kada si daleko, nostalgija zove.","Iz dna duše čut ćeš poziv zemlje ove.","Na njedarca svoja k'o voljena žena,","radosno te prima, to je dužnost njena."],"en":["Whenever you're far off, nostalgia calls you near;","from deep within your soul, this land's own call rings clear.","Upon her own dear breast, just like a well-loved wife,","she gladly takes you in: that is her part in life."],"day":"11-13"},{"slug":"ne-odlazi-draga","title_hr":"Ne odlazi, draga","title_en":"Do Not Leave, My Darling","hr":["Da utopim bol, patnju i tugu,","u naručju slatkom, mila, tvome.","Biti svaki trenutak sa tobom,","to je slatki melem srcu mome."],"en":["Let me drown my pain, my grief and sorrow","in your sweet embrace, my dear, my own.","Just to be with you in every moment","is the sweetest balm my heart has known."],"day":"11-14"},{"slug":"invalid","title_hr":"Invalid","title_en":"The Invalid","hr":["Tek vidim,","neke granate,","krvavu žetvu.","I vidim,","tužnu prazninu,","što mjesto noge zja."],"en":["I only see","the bloody harvest","of some shell's burst.","And I see","the sad emptiness","gaping where a leg should go."],"day":"11-15"},{"slug":"ne-krivi-mene","title_hr":"Ne krivi mene","title_en":"Don't Blame Me","hr":["Ne krivi mene što te silno ljubim","i ljubav žarku je u srcu nosim.","Ne krivi mene što za tobom žudim","i ljubav tvoju kao prosjak prosim."],"en":["Don't blame me that my love for you is strong,","and in my heart a burning love I bear;","don't blame me that for you I yearn and long","and beg you for your love, a beggar's prayer."],"day":"11-16"},{"slug":"sokacki-obicaji","title_hr":"Šokački običaji","title_en":"Šokac Customs","hr":["Nema više konja da dvorištem njište,","mjesto njih traktori sokacima bruje.","Nema mladih snaša da u kolu vrište,","sve je utihnulo, ništa se ne čuje."],"en":["There are no more horses in farmyards to neigh,","in their place, only tractors go droning down lanes;","no young wives in the kolo now whooping away,","all has fallen silent, and no sound remains."],"day":"11-17"},{"slug":"vojnikova-majka","title_hr":"Vojnikova majka","title_en":"The Soldier's Mother","hr":["Ubiše mi sina,","od osamnaest godina.","Život je izgubio u boju,","braneći domovinu svoju."],"en":["They killed my son,","eighteen years beneath the sun.","He fell in battle, making a stand,","defending his own native land."],"day":"11-18","occ_hr":"Dan sjećanja na Vukovar","occ_en":"Vukovar Remembrance Day"},{"slug":"starac","title_hr":"Starac!","title_en":"The Old Man","hr":["Vrati bože, osmjeh, radost,","svakom stvoru da se divim.","Slatku ljubav, sretnu mladost","još jedanput da proživim."],"en":["Give me back, O God, my smile","and the joy to marvel still;","sweetest love and youth, a while","let me live them, if you will."],"day":"11-19"},{"slug":"zivotna-premija","title_hr":"Životna premija","title_en":"Life's Bonus","hr":["Mili Bože, lijepi dan me čeka,","barem da je ovako dovijeka."],"en":["Dear Lord, a lovely day lies here in store;","if only it were so for evermore!"],"day":"11-20","occ_hr":"napisano na današnji dan, 2007.","occ_en":"written on this day in 2007"},{"slug":"snivam","title_hr":"Snivam","title_en":"I Dream","hr":["A kada se raspline noć","i zlatna zora zarudi,","tvog srca tihi kucaj,","mene iz snova budi."],"en":["And when darkness melts away","and the golden dawn shines bright,","the soft beating of your heart","wakes me from my dreams of night."],"day":"11-21"},{"slug":"sretan-imendan-priji-kati","title_hr":"Sretan imendan priji Kati","title_en":"A Happy Name Day to Our Prija Kata","hr":["Mili, Bože, što godine lete,","pa na pleća kao teret slete.","Zima tiho kuca mi na vrata,","eto stiže već i sveta Kata."],"en":["Dear God, how swiftly all the years fly by,","and on our shoulders like a burden lie;","the winter's softly knocking at my door,","and here's Saint Kata, come around once more."],"day":"11-22","occ_hr":"napisano na današnji dan, 2011.","occ_en":"written on this day in 2011"},{"slug":"saljes-li-mi-snove","title_hr":"Šalješ li mi snove","title_en":"Do You Send Me Dreams","hr":["A čim se probudim i otvorim oči,","u zoru ranu kad se gase snovi,","na tebe mislim da ćeš meni doći,","i tako dani započinju novi."],"en":["And when I wake and open up my eyes to see","the early dawn, as all my dreams go out,","I think of you, that you will come to me,","and that is how the new days come about."],"day":"11-23","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"duh-crnoga-sama","title_hr":"Duh crnoga Sama","title_en":"Black Sam's Ghost","hr":["Kako su na platnu promicale sjene","i ljubav se tako rađala međ' nama.","Gledala si krišom vatrene mi zjene,","a film se zvao \"Duh crnoga Sama.\""],"en":["And as across the screen the shadows flickered past,","and love was born between us as we sat engrossed,","your secret glances at my fiery eyes were cast,","and the film that was showing was called \"Black Sam's Ghost\"."],"day":"11-24"},{"slug":"vrati-se","title_hr":"Vrati se","title_en":"Come Back","hr":["Vrati se!","Budimo sretni k'o prije.","Ujutro kada se budiš,","pričaj mi svoje snove.","Spasi ljubav našu,","dok kasno nije."],"en":["Come back!","Let us be happy as before.","Each morning, when you wake,","tell me what you dreamed.","Save this love of ours","before it is no more."],"day":"11-25","occ_hr":"napisano na današnji dan, 1974.","occ_en":"written on this day in 1974"},{"slug":"sopje-selo-moga-djetinjstva","title_hr":"Sopje, selo moga djetinjstva","title_en":"Sopje, Village of My Childhood","hr":["Još se sjećam svog djetinjstva,","divna nošnja se nosila,","što je bila ukras selu,","folkloraše okitila."],"en":["I recall my childhood still:","lovely costumes then were worn,","the adornment of the village,","and the dancers they'd adorn."],"day":"11-26","occ_hr":"napisano na današnji dan, 2010.","occ_en":"written on this day in 2010"},{"slug":"dodi-mi-draga","title_hr":"Dođi mi, draga","title_en":"Come to Me, Darling","hr":["U zagrljaj dođi meni,","kad zvjezdane budu noći.","Probudi moj život sneni,","a poljupcem sklopi oči."],"en":["Come and hold me close and tight","when the nights have starry skies;","wake my drowsy life to light,","with a kiss then close my eyes."],"day":"11-27"},{"slug":"zudnja","title_hr":"Žudnja","title_en":"Yearning","hr":["Ja od tebe sad odlazim","s mnogo bola pa i šutnje:","novom stazom sada gazim,","sad ostaju ipak žudnje."],"en":["Now from you I go away","with much pain, and silence too;","on a new road I make my way,","yet my yearning stays with you."],"day":"11-28"},{"slug":"kolinje-u-drenovcima","title_hr":"Kolinje u Drenovcima","title_en":"Kolinje in Drenovci","hr":["Drenovčani, plemeniti ljudi,","marljivi su i pitome ćudi,","oni štuju stare običaje,","pa kolinje po tri dana traje."],"en":["The Drenovci folk are noble people, true,","hard-working, and of gentle nature, too;","they honour all the customs of the past,","so for three days their kolinje will last."],"day":"11-29","occ_hr":"Vrijeme kolinja","occ_en":"Kolinje season"},{"slug":"zelja","title_hr":"Želja!","title_en":"Desire!","hr":["Od čežnje gorim,","al' ne mogu da sagorim","u divljem plamenu","svojih želja."],"en":["With longing I burn,","but to ash I can't turn","in the wild flame","of my desire."],"day":"11-30","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"zimska-idila","title_hr":"Zimska idila","title_en":"Winter Idyll","hr":["Mraz je pao i studen me hvata,","došla zima i na moja vrata.","Sav se ježim kad vjetar zacvili,","a da li ste ogrjev nabavili?"],"en":["The frost has come, the cold has gripped me fast,","and winter's reached my door as well at last.","I shiver all over when the wind wails high,","and have you laid your winter firewood by?"],"day":"12-01"},{"slug":"prva-zekina-zima","title_hr":"Prva Zekina zima","title_en":"Little Bunny's First Winter","hr":["Poželio zeko mali","majku, da mu krevet grije,","od snijega je polje bijelo,","cijele noći spav'o nije."],"en":["Little bunny longed for Mother","there to warm his bed at night;","not a wink he slept till morning,","and the field was snowy white."],"day":"12-02"},{"slug":"sopje-nekada-i-sada","title_hr":"Sopje nekada i sada","title_en":"Sopje, Then and Now","hr":["Daleko sam od mog sela,","al' me srce k njemu vuče.","Još se sjećam onih dana,","kad sam bio tu kod kuće."],"en":["I am far from my own village,","but my heart pulls me that way;","I remember still the time","when at home I used to stay."],"day":"12-03"},{"slug":"ovaj-dom-je-utociste-vase","title_hr":"Ovaj dom je utočište vaše","title_en":"This Home Is Your Refuge","hr":["Kad vas jutro iz toplog sna budi","i kad danak na ljepotu sluti,","a prijatelj kraj tebe nasmije,","eto, to su životne premije."],"en":["When morning wakes you from your cosy bed","and the young day foretells fine things ahead,","and when a friend beside you smiles at you,","why, these are life's own bonuses come due."],"day":"12-04","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"hvala-ti-draga","title_hr":"Hvala ti, draga!","title_en":"Thank You, Darling!","hr":["Na pogledu tvome, velika ti hvala,","što me cijelog dana, nježno, toplo grije,","kao ono nekad u davnini prije."],"en":["And for that glance of yours, I give you heartfelt thanks,","that warms me tenderly all day with gentle glow,","the way it used to warm me once, so long ago."],"day":"12-05"},{"slug":"djecji-snovi","title_hr":"Dječji snovi","title_en":"Children's Dreams","hr":["Zapamtite, tko je mio","taj po noći divno sanja,","ali tko je zločest bio,","toga ljuta šiba ganja."],"en":["So remember: each good child","has sweet dreams the whole night through;","but the naughty and the wild,","feel the stinging switch pursue."],"day":"12-06","occ_hr":"Sveti Nikola","occ_en":"St Nicholas' Day"},{"slug":"osvrt-na-ljubav","title_hr":"Osvrt na ljubav","title_en":"A Look at Love","hr":["Sretan mačor u krevetu prede,","sve što treba u krilašcu nađe,","tu su snovi koji zlata vrijede,","ništa nema od ljubavi slađe."],"en":["In bed a happy tomcat purrs, all curled,","in a little lap he finds all he needs, complete;","here are dreams worth all the gold in the world,","nothing can compare with love so sweet."],"day":"12-07","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"ne-budi-me-majko-rano","title_hr":"Ne budi me, majko, rano","title_en":"Don't Wake Me Early, Mother","hr":["Ne budi me, majko, rano.","Ne kidaj mi divne snove,","kada zoveš moje ime,","mislim da me draga zove."],"en":["Mother, do not wake me early,","leave my lovely dreams unbroken:","when you call my name, I fancy","it's my darling who has spoken."],"day":"12-08"},{"slug":"sto-mi-to-treba","title_hr":"Što mi to treba","title_en":"What Do I Need It For","hr":["I dok ljubav njena moje srce vreba,","razum mi govori što mi sve to treba.","Dotle sreću svoju ja bacam sa neba,","zar da takav život živim do pogreba."],"en":["And while her love lies waiting for my heart nearby,","my reason asks: what do I need it for, and why?","Meanwhile I fling my happiness down from the sky:","must I live such a life until the day I die?"],"day":"12-09"},{"slug":"tuzno-je-biti-sam","title_hr":"Tužno je biti sam","title_en":"It's Sad to Be Alone","hr":["Zato si nađi,","životnog druga,","nikad ne budi sam.","Život je slađi,","manja je tuga,","vjeruj mi,","ja to znam."],"en":["Go, then, seek and find","a companion true;","never be alone.","Life's more sweet, more kind,","and less sorrow, too;","trust me,","this I've known."],"day":"12-10","occ_hr":"napisano na današnji dan, 1989.","occ_en":"written on this day in 1989"},{"slug":"etno-kuca-semialjac-kate","title_hr":"Etno kuća Semialjac Kate","title_en":"Kata Semialjac's Ethno House","hr":["U spavaćoj krevet snove sanja,","u mislima svoje gazde zove,","tužan stoji u svojoj samoći,","a htio bi da im pruži snove."],"en":["The bed within the bedroom dreams its dreams,","in thought it calls its masters, calls in vain;","it stands there sad, alone in solitude,","and longs to give them dreams to dream again."],"day":"12-11"},{"slug":"puna-casa-ljubavi","title_hr":"Puna čaša ljubavi","title_en":"A Glass Brimming with Love","hr":["U mom srcu i u duši,","ljubavi je puna čaša,","ako me još, draga, voliš","vrati mi se ovog časa."],"en":["In my heart and in my soul","love has filled a glass for two;","if you love me still, my darling,","come back now, this hour, please do!"],"day":"12-12","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"sveta-lucija","title_hr":"Sveta Lucija","title_en":"Saint Lucy","hr":["Svima vama što ste u toj tami","usamljeni u životu sami,","nek' vam teku u ljepoti dani,","od LUCIJE SVETE OBASJANI."],"en":["All of you who in that darkness stay,","lonely and alone along life's way,","may your days flow on in beauty bright,","RADIANT WITH HOLY LUCY'S LIGHT."],"day":"12-13","occ_hr":"Sveta Lucija","occ_en":"St Lucy's Day"},{"slug":"poezijski-rad-kroz-zivot","title_hr":"Poezijski rad kroz život","title_en":"A Life's Work in Poetry","hr":["Za kulturu obol dao,","bio sam na puno sijela,","mnoge ljude radovao,","uzdignuta uvijek čela."],"en":["To our culture I gave my part,","went to sijela far and wide;","gladdened many a human heart,","with my head held high in pride."],"day":"12-14"},{"slug":"protiv-svoje-volje","title_hr":"Protiv svoje volje","title_en":"Against My Will","hr":["Kad sam bio u trbuhu majke,","nikada mi nije bilo bolje.","Mene ništa ni pitali nisu,","rodiše me protiv moje volje."],"en":["When I was lying in my mother's womb,","I never had it better there. Until,","without so much as asking what I wished,","they bore me into life against my will."],"day":"12-15","occ_hr":"napisano na današnji dan, 1990.","occ_en":"written on this day in 1990"},{"slug":"diljem-slavonije","title_hr":"Diljem Slavonije","title_en":"All Across Slavonia","hr":["U Kutjevu zaustavim vrijeme,","pijuć' vino nekoliko dana,","uz tambure i Šokice mlade,","volim život i to mi je mana."],"en":["In Kutjevo I make the time stand still,","drinking wine as several days go by,","with the tamburas and young Šokice;","I love life, a fault I can't deny."],"day":"12-16","occ_hr":"napisano na današnji dan, 1993.","occ_en":"written on this day in 1993"},{"slug":"dragice","title_hr":"Dragice!","title_en":"Dragica!","hr":["Kao rijeka bez povratka,","isto tako život teče.","Blago onom ljudskom stvoru,","tko zdravstvene ima sreće."],"en":["Like a river never turning","back, so too our life flows on;","blessed is the human creature","who has health to count upon."],"day":"12-17","occ_hr":"napisano na današnji dan, 2012.","occ_en":"written on this day in 2012"},{"slug":"cestitka-unucima","title_hr":"Čestitka unucima","title_en":"New Year's Greetings to Our Grandchildren","hr":["Dobro zdravlje pored svega,","to je naša želja jaka!","Sve najbolje vama žele","vaši dobri djed i baka!"],"en":["And good health, above all things:","that's the wish we firmly hold!","All the best to you are sending","Grandpa, Grandma, good as gold!"],"day":"12-18","occ_hr":"napisano na današnji dan, 1988.","occ_en":"written on this day in 1988"},{"slug":"majka","title_hr":"Majka","title_en":"Mother","hr":["Kad čuje bilo srca njenog,","toplinu osjeti majke,","ona je njemu božica sreće,","ljepša od svake bajke."],"en":["When it hears her heart's soft beating","and its mother's warmth is there,","she's the goddess of its joy and gladness,","than all fairy tales more fair."],"day":"12-19"},{"slug":"zanos","title_hr":"Zanos","title_en":"Rapture","hr":["Oh, ljubavi moja!","Slatka si i mila,","kao majka čedu,","kad raširi krila."],"en":["Oh, my love, my darling!","You're so sweet and mild,","like a mother spreading","her wings above her child."],"day":"12-20","occ_hr":"napisano na današnji dan, 1973.","occ_en":"written on this day in 1973"},{"slug":"koliko-htjenja","title_hr":"Koliko htjenja","title_en":"So Much Longing","hr":["Koliko htjenja u noći toj!","Bar da se usne spoje.","A tebe nema u ovom trenu,","tužno je srce moje."],"en":["Oh, how much longing in that night!","If our lips at least could meet!","But you're not here with me this moment,","and my heart is sad, my sweet."],"day":"12-21"},{"slug":"draga-generacijo-2013","title_hr":"Draga generacijo!","title_en":"My Dear Generation!","hr":["Među ljudstvom neka sloga vlada","Ne bilo vam staračkoga jada","Da se lakše u životu diše","I ratova da ne bude više."],"en":["May among all folk accord hold sway,","may the woes of old age stay away,","so that breathing's easier in life,","and no more of wars and all their strife."],"day":"12-22","occ_hr":"napisano na današnji dan, 2013.","occ_en":"written on this day in 2013"},{"slug":"ljubav-se-ne-mjeri","title_hr":"Ljubav se ne mjeri","title_en":"Love Is Not Measured","hr":["Najljepše sam pjesme tebi poklonio,","i najdraže snove ja sam s tobom snio.","Sa usana tvojih sladak med sam pio.","I najslađu ljubav s tobom provodio."],"en":["The loveliest songs I ever wrote, I gave to you;","and with you dreamed the dearest dreams, as lovers do;","sweet honey from your lips in long, deep draughts I drew,","and spent with you the sweetest love I ever knew."],"day":"12-23","occ_hr":"napisano na današnji dan, 1975.","occ_en":"written on this day in 1975"},{"slug":"ide-bozic-i-sveti-nikola-i-poklona-nosi-puna-kola","title_hr":"Ide Božić i sveti Nikola i poklona nosi puna kola","title_en":"Here Come Christmas and Saint Nicholas with a Cartful of Gifts","hr":["Na Badnjak smo sretni bili","i božićni bor kitili.","Stavljali smo sve ukrase,","još jabuke i orase."],"en":["Christmas Eve, how glad were we,","trimming up the Christmas tree!","We hung baubles here and there,","apples, walnuts, everywhere."],"day":"12-24","occ_hr":"Badnjak","occ_en":"Christmas Eve"},{"slug":"gospodi-ani-gillinger-iz-ivankova","title_hr":"Gospođi Ani Gillinger iz Ivankova","title_en":"To Mrs Ana Gillinger of Ivankovo","hr":["Nek' Vam bude SRETAN BOŽIĆ","I GODINA ova NOVA,","a najviše dobrog zdravlja:","želi Ivo iz Valpova!"],"en":["May you have a MERRY CHRISTMAS","and a NEW YEAR's happy glow;","and good health, above all things,","wishes Ivo from Valpovo!"],"day":"12-25","occ_hr":"Božić","occ_en":"Christmas Day"},{"slug":"ja-volim","title_hr":"Ja volim","title_en":"What I Love","hr":["Ja volim tihe,","zvjezdane noći.","I topli kutak","ljubavnog žara.","Skromni, mali,","tihi, mili dom."],"en":["I love the quiet,","starry nights,","and a warm corner","where love's embers glow.","Small and modest,","a quiet, homely nest."],"day":"12-26","occ_hr":"Sveti Stjepan","occ_en":"St Stephen's Day"},{"slug":"noge-bose-a-cipele-cure","title_hr":"Noge bose a cipele cure","title_en":"Bare Feet and Leaky Shoes","hr":["Pukla mi je cipela na peti,","pa mi stalno rupa na pameti.","Rupu gledam, mislim sad je zgoda,","pa popravim dok ne uđe voda."],"en":["My shoe's burst open at the heel behind,","and so I've got a hole upon my mind.","I eye the hole and think: now is the day","to fix it, before water finds its way."],"day":"12-27","occ_hr":"napisano na današnji dan, 1996.","occ_en":"written on this day in 1996"},{"slug":"sretna-vam-nova-godina-draga-generacijo","title_hr":"Sretna vam Nova godina, draga generacijo","title_en":"A Happy New Year to You, Dear Generation","hr":["Uskoro nam stiže Novo Ljeto,","što nam nosi neka bude sretno,","puno sreće i zdravlja i para,","sve probleme nek' odnese stara."],"en":["The New Year's soon upon us: may it be","that what it brings brings joy to you and me,","with lots of luck and health and cash to hold;","may all our troubles go off with the old."],"day":"12-28"},{"slug":"hej-zivote","title_hr":"Hej živote","title_en":"Hey There, Life","hr":["Hej živote, malo stani!","Sretna zoro, daj osvani!","Radosnice, suzo, kani!","Da nam budu ljepši dani.","Dobro zdravlje, sreće puno,","povrh svega, zlatno runo!"],"en":["Hey there, life, don't rush, go slow!","Happy dawn, rise up and glow!","Tears of joy, come, overflow,","so our days more lovely grow!","Health and happiness in store,","and the Golden Fleece, what's more!"],"day":"12-29"},{"slug":"cestitka-unucima","title_hr":"Čestitka unucima","title_en":"New Year's Greetings to Our Grandchildren","hr":["Godinicu sretnu Novu,","čestitamo vama svima!","I darova puna kola,","našim dragim unucima!"],"en":["Happy little New Year's greetings","we send out to all of you!","And a cartload full of presents","for our dear grandchildren too!"],"day":"12-30"},{"slug":"novogodisnje-zelje","title_hr":"Novogodišnje želje","title_en":"New Year's Wishes","hr":["Novo ljeto kad ura najavi,","da sam s tobom i da se veselim,","kad se radost na tom svijetu slavi,","da ti prvi čestitke poželim."],"en":["When the clock rings in the year that's new,","may I be at your side, rejoicing here;","when joy is celebrated the whole world through,","may I be first to wish you a happy year."],"day":"12-31","occ_hr":"Stara godina","occ_en":"New Year's Eve"}];
